insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('schdoodsbiaga', 'Schdoodsbiaga', '', '', '', '', 'Staatsbürger', '[{"kategorie": "", "text": "Die Staatsbürgerschaft verleiht dem Staatsbürger eine rechtliche und politische Zugehörigkeit zum [[Staat]] Österreich und garantiert den Zugang zu grundlegenden Rechten und politischen Teilhabemöglichkeiten"}, {"kategorie": "", "text": "Die Staatsbürgerschaft macht eine Person zu einem rechtlichen Mitglied des österreichischen Staates. Sie begründet die Bindung an den Staat und verleiht den Staatsbürgern das Recht auf staatlichen Schutz und Unterstützung"}, {"kategorie": "", "text": "Staatsbürger haben Anspruch auf Reisepässe, die vom [[österreichischen]] Staat ausgestellt werden und den vollen diplomatischen Schutz im In- und Ausland garantieren"}, {"kategorie": "", "text": "Staatsbürger haben politische Rechte, die es ihnen ermöglichen, an der [[politischen]] Willensbildung teilzunehmen. Dazu gehört das aktive Wahlrecht (das Recht, bei Wahlen zu wählen) und das passive Wahlrecht (das Recht, für ein politisches Amt zu kandidieren)"}, {"kategorie": "", "text": "Mit der österreichischen Staatsbürgerschaft sind auch bestimmte Pflichten verbunden. Dazu zählen die Einhaltung der Gesetze, die Zahlung von Steuern und die Pflicht zur Schulbildung für Kinder. Männliche Staatsbürger sind außerdem zur [[Wehrpflicht]] oder zum [[Zivildienst]] verpflichtet, sofern keine Befreiung vorliegt"}, {"kategorie": "", "text": "Als Staatsbürger genießen Personen in Österreich alle durch die [[Verfassung]] garantierten [[Grundrechte]]. Dazu gehören unter anderem das Recht auf [[Meinungsfreiheit]], [[Religionsfreiheit]], [[Versammlungsfreiheit]], [[Pressefreiheit]] und der [[Schutz]] der Privatsphäre. Diese Rechte sind durch die [[Verfassung]] und die [[Europäische]] Menschenrechtskonvention (EMRK) geschützt, die in Österreich Verfassungsrang hat"}, {"kategorie": "", "text": "[[Österreichische]] Staatsbürger haben Anspruch auf staatliche Unterstützung, wie zum Beispiel durch das Bildungs-, Gesundheits- und Sozialsystem. Sie haben auch Zugang zu Leistungen wie Pensionen, Arbeitslosengeld und Familienbeihilfen. Im Ausland haben Staatsbürger Anspruch auf konsularischen Schutz durch österreichische Botschaften und Konsulate. Der Staat setzt sich für den Schutz seiner Bürger ein, wenn sie in Not geraten"}, {"kategorie": "", "text": "Die [[österreichische]] Staatsbürgerschaft kann durch Geburt, Heirat, Einbürgerung oder in bestimmten Fällen durch Abstammung erworben werden. Kinder, die von einem oder beiden österreichischen Staatsbürgern abstammen, erhalten automatisch die Staatsbürgerschaft."}]'::jsonb, ''),
  ('bueaga', 'Büaga', '', '', '', '', 'Bürger', '[{"kategorie": "pol.", "text": "\"Person, die entweder die österreichische Staatsbürgerschaft besitzt oder dauerhaft in Österreich lebt und bestimmte Rechte und Pflichten in der [[Gesellschaft]] wahrnimmt\""}, {"kategorie": "", "text": "Der Bürger spielt eine zentrale Rolle in der [[Demokratie]] und ist aktiv an der [[politischen]] Willensbildung sowie der Ausübung von staatsbürgerlichen Rechten beteiligt"}, {"kategorie": "", "text": "Bürger in Österreich haben das Recht zu wählen (aktives Wahlrecht) und das Recht, für politische Ämter zu kandidieren (passives Wahlrecht). Sie wählen die Mitglieder des [[Nationalrats]], der [[Landtage]] und der [[Gemeinderäte]]. Durch Wahlen und die Beteiligung an [[Volksbegehren]] oder [[Volksabstimmungen]] üben Bürger einen direkten Einfluss auf die politische Willensbildung aus und tragen zur Gestaltung der politischen Agenda des Landes bei"}, {"kategorie": "", "text": "Neben Rechten haben Bürger auch Pflichten. Dazu gehören die Einhaltung der [[Gesetze]], das Zahlen von Steuern, die Schulpflicht für Kinder und in bestimmten Fällen die [[Wehrpflicht]] oder [[Zivildienstpflicht]] für männliche Staatsbürger"}, {"kategorie": "", "text": "Die österreichische [[Verfassung]] garantiert Bürgern grundlegende Rechte wie das Recht auf [[Meinungsfreiheit]], [[Versammlungsfreiheit]], [[Pressefreiheit]] und den [[Schutz]] der Privatsphäre. Die [[Europäische]] Menschenrechtskonvention (EMRK), die in Österreich Verfassungsrang hat, erweitert diese Rechte und schützt die Bürger vor staatlichen Übergriffen"}, {"kategorie": "", "text": "Während [[Staatsbürger]] volle politische Rechte haben, gibt es auch Nicht-Staatsbürger (z. B. EU-Bürger oder Drittstaatsangehörige), die in Österreich leben und bestimmte Teilhabe-Möglichkeiten besitzen. EU-Bürger können etwa bei [[Gemeinderatswahlen]] und [[Europawahlen]] mitwählen, jedoch nicht bei [[Nationalratswahlen]]. Der Erwerb der [[Staatsbürgerschaft]] durch Einbürgerung ermöglicht es Nicht-Staatsbürgern, nach einem bestimmten Zeitraum in Österreich ebenfalls die vollen Bürgerrechte zu erhalten"}, {"kategorie": "", "text": "Bürger in Österreich haben Anspruch auf staatliche Unterstützung in Form von sozialen Leistungen wie Arbeitslosengeld, Pensionen, Bildung und Gesundheitsversorgung. Der Staat ist verpflichtet, die grundlegenden Bedürfnisse der Bürger zu sichern"}, {"kategorie": "", "text": "Die politische und rechtliche Stellung des Bürgers ist ein zentraler Bestandteil der [[Demokratie]] und [[Rechtsstaatlichkeit]] in Österreich."}]'::jsonb, ''),
  ('atv', 'ATV', '', '', '', '', 'ATV', '[{"kategorie": "", "text": "Der Sender bietet eine breite Palette von Programmen, darunter Nachrichten, Unterhaltungsformate, Serien, Reality-TV und Dokumentationen"}, {"kategorie": "", "text": "ATV ist ein zentraler Bestandteil der österreichischen privaten Fernsehlandschaft und richtet sich an ein breites Publikum"}, {"kategorie": "", "text": "Seit 2017 gehört ATV zur ProSiebenSat.1 PULS 4 Gruppe, die zu den größten privaten Medienunternehmen im deutschsprachigen Raum zählt. Diese Übernahme hat es ATV ermöglicht, von Synergien innerhalb der Gruppe zu profitieren und zusätzliche Ressourcen für die Programmgestaltung zu nutzen"}, {"kategorie": "", "text": "ATV richtet sich an eine breite Zielgruppe, insbesondere an Zuschauer, die an unterhaltsamen, leicht zugänglichen Formaten interessiert sind. Mit einer Mischung aus Reality-TV, Nachrichten und Filmen spricht der Sender sowohl junge Erwachsene als auch Familien an."}]'::jsonb, ''),
  ('gsoeschoft', 'Gsöschoft', '', '', '', '', 'Gesellschaft', '[{"kategorie": "pol.", "text": "\"Gesamtheit der Menschen, die in einem gemeinsamen sozialen, politischen, wirtschaftlichen und kulturellen Rahmen leben\""}, {"kategorie": "", "text": "Sie ist geprägt von historischen Entwicklungen, kulturellen Traditionen und einer gemeinsamen rechtlichen und politischen Ordnung"}, {"kategorie": "", "text": "Die österreichische Gesellschaft ist vielfältig und setzt sich aus verschiedenen sozialen Gruppen und Gemeinschaften zusammen, die durch gemeinsame Werte, Normen und Strukturen verbunden sind"}, {"kategorie": "", "text": "Die österreichische Gesellschaft ist stark von ihrer kulturellen Vielfalt geprägt. Österreich hat eine lange Geschichte als multikultureller Staat, besonders in den Städten wie Wien, wo Menschen unterschiedlicher Herkunft und Religion zusammenleben"}, {"kategorie": "", "text": "Der Einfluss der Geschichte, insbesondere der [[Habsburgermonarchie]], hat eine pluralistische und kosmopolitische Gesellschaft geformt. Kulturelle Institutionen wie Theater, Musik und Kunst haben eine zentrale Rolle in der österreichischen Identität."}]'::jsonb, ''),
  ('parlamentsmeaheit', 'Parlamentsmeaheit', '', '', '', '', 'Parlamentsmehrheit', '[{"kategorie": "pol.", "text": "\"Mehrheit der [[Abgeordneten]] in einem [[Parlament]], die eine politische Richtung oder [[Partei]](en) unterstützen\""}, {"kategorie": "", "text": "Diese Mehrheit ist entscheidend für die Durchsetzung von Gesetzen und die Stabilität der Regierung in einem parlamentarischen System"}, {"kategorie": "", "text": "Absolute Mehrheit: Eine [[absolute]] Mehrheit bedeutet, dass mehr als die Hälfte aller Abgeordneten im Parlament eine Regierung oder bestimmte Gesetzesvorschläge unterstützt. In Österreich besteht der [[Nationalrat]] aus 183 Abgeordneten, sodass eine absolute Mehrheit mindestens 92 Stimmen erfordert"}, {"kategorie": "", "text": "Regierungsmehrheit: In [[parlamentarischen]] Systemen wie dem in Österreich ist die [[Regierungsmehrheit]] entscheidend. Sie ermöglicht es der Regierung, Gesetze durchzusetzen und das Vertrauen des Parlaments zu sichern. Eine Regierung ist auf die Unterstützung der Parlamentsmehrheit angewiesen, um stabil zu regieren und nicht durch ein [[Misstrauensvotum]] abgesetzt zu werden"}, {"kategorie": "", "text": "[[Koalitionsmehrheit]]: Da es in Österreich häufig keine Partei gibt, die alleine eine absolute Mehrheit hat, bilden mehrere Parteien eine [[Koalition]], um gemeinsam eine Parlamentsmehrheit zu erreichen.\nDiese Koalition regiert zusammen und teilt sich die Regierungsverantwortung, um die Mehrheit im Nationalrat zu sichern"}, {"kategorie": "", "text": "Relative Mehrheit: Eine [[relative]] Mehrheit bedeutet, dass eine Partei oder ein Block die meisten Stimmen hat, aber nicht unbedingt mehr als die Hälfte der Sitze. In Österreich ist das oft ein Ausgangspunkt für Koalitionsverhandlungen"}, {"kategorie": "", "text": "Die [[Parteien]], die nicht zur Parlamentsmehrheit gehören, bilden die [[Opposition]]. Ihre Aufgabe ist es, die [[Regierung]] zu kontrollieren und alternative Vorschläge zu machen. Die Minderheit kann [[Gesetzesvorschläge]] kritisch hinterfragen und den [[politischen]] Diskurs anregen, hat jedoch nicht genug Stimmen, um alleine [[Gesetze]] zu verhindern oder durchzusetzen."}]'::jsonb, ''),
  ('gesetzgebung', 'Gesetzgebung', '', '', '', '', 'Gesetzgebung', '[{"kategorie": "pol.", "text": "\"Prozess, durch den rechtliche Normen und Gesetze geschaffen werden. Dieser Prozess wird von gesetzgebenden Organen, insbesondere dem [[Nationalrat]], dem [[Bundesrat]] und den [[Landtagen]] auf Länderebene, durchgeführt\""}, {"kategorie": "", "text": "Merkmale der Gesetzgebung in Österreich:\n(i ) [[Parlamentarisches]] System (die Gesetzgebung auf Bundesebene erfolgt hauptsächlich durch den [[Nationalrat]], der das zentrale gesetzgebende Organ ist. Der [[Bundesrat]] hat in vielen Fällen ein Einspruchsrecht, kann aber Gesetze nicht endgültig verhindern. Sein Einfluss ist somit eher beschränkter als der des Nationalrats. Auf Länderebene haben die [[Landtage]] die Zuständigkeit für die Gesetzgebung in Bereichen, die laut Bundesverfassung den Ländern vorbehalten sind [z. B. im Schul- und Baurecht]),  (ii) [[Gewaltenteilung]] (die Gesetzgebung [[[Legislative]]] ist klar von der [[Exekutive]] [[[Regierung]]] und der [[Judikative]] [[[Gerichte]]] getrennt. Diese Trennung gewährleistet ein System der gegenseitigen Kontrolle und Balance der [[Staatsgewalten]]),   (iii) [[Bundesverfassung]] (die Grundlage der Gesetzgebung in Österreich ist die Bundesverfassung. Alle Gesetze müssen im Einklang mit dieser stehen. Der [[Verfassungsgerichtshof]] (VfGH) überwacht die Verfassungsmäßigkeit von Gesetzen)"}, {"kategorie": "", "text": "[[Gesetzgebungsverfahren]]: (i) Die Gesetzgebung beginnt in der Regel mit einem [[Gesetzesvorschlag]] oder [[Gesetzesentwurf]], der entweder von der [[Regierung]], von [[Abgeordneten]] oder durch [[Volksbegehren]] eingebracht werden kann;  (ii) Nach Beratung und Abstimmung im [[Nationalrat]] geht das Gesetz zur Genehmigung an den [[Bundesrat]] und wird nach Annahme durch den [[Bundespräsidenten]] beurkundet. Nach der Kundmachung im [[Bundesgesetzblatt]] tritt das Gesetz in Kraft"}, {"kategorie": "", "text": "[[Föderalismus]]: Österreich ist ein föderaler Staat, in dem sowohl der [[Bund]] als auch die [[Länder]] Gesetzgebungsbefugnisse haben. Während der Bund für Bereiche wie Außenpolitik und Strafrecht zuständig ist, haben die Länder eigenständige Gesetzgebungsrechte in Angelegenheiten wie Raumplanung und Naturschutz"}, {"kategorie": "", "text": "Die Gesetzgebung in Österreich ist ein zentraler Bestandteil der [[Demokratie]] und stellt sicher, dass Gesetze in einem transparenten und geregelten Verfahren durch die [[Volksvertretung]] geschaffen werden. Die klare Gewaltenteilung sowie die föderalen Strukturen tragen dazu bei, dass die verschiedenen staatlichen Ebenen – Bund und Länder – an diesem Prozess beteiligt sind."}]'::jsonb, ''),
  ('rechtschbrechung', 'Rechtschbrechung', '', '', '', '', 'Rechtsprechung', '[{"kategorie": "pol.", "text": "\"Ausübung der richterlichen Gewalt durch [[Gerichte]], die gerichtliche Entscheidungen in Rechtsstreitigkeiten treffen\""}, {"kategorie": "", "text": "Die Rechtsprechung umfasst das gesamte System von Gerichten, die [[Gesetze]] anwenden und auslegen, um Rechtsfragen zu klären und Rechtssicherheit zu schaffen"}, {"kategorie": "", "text": "In Österreich bezieht sich die Rechtsprechung vor allem auf die Urteile und Entscheidungen der [[ordentlichen]] Gerichte (wie [[Bezirksgerichte]], [[Landesgerichte]], [[Oberlandesgerichte]] und den [[Obersten]] Gerichtshof), sowie auf [[Verfassungs-]] und [[Verwaltungsgerichte]], die für unterschiedliche Rechtsgebiete zuständig sind"}, {"kategorie": "", "text": "Merkmale der Rechtsprechung in Österreich: (i) [[Gewaltenteilung]] (die Rechtsprechung ist ein eigenständiger Bereich der [[Staatsgewalt]], getrennt von der [[Gesetzgebung]] und [[Verwaltung]]),  (ii) Präzedenzwirkung (Gerichtsurteile, insbesondere von Höchstgerichten wie dem [[Obersten]] Gerichtshof (OGH), dem [[Verfassungsgerichtshof]] (VfGH) und dem [[Verwaltungsgerichtshof]] (VwGH), haben eine wegweisende Wirkung für zukünftige Fälle,  (iii) Zweigliedrigkeit (das österreichische Rechtssystem teilt sich in [[Zivil-]] und [[Strafrecht]] einerseits sowie [[öffentliches]] Recht [Verfassungs- und Verwaltungsrecht] andererseits), (iv) Verfassungsgerichtsbarkeit (der Verfassungsgerichtshof überprüft die Verfassungsmäßigkeit von Gesetzen und schützt die Grundrechte der Bürger)"}, {"kategorie": "", "text": "In der Praxis bedeutet Rechtsprechung also die Anwendung des geltenden Rechts auf konkrete Fälle durch unabhängige Gerichte, die auch der Kontrolle durch [[Rechtsmittel]] unterliegt."}]'::jsonb, ''),
  ('gericht', 'Gericht', '', '', '', '', 'Gericht', '[{"kategorie": "pol.", "text": "\" staatliche Institution der [[Judikative]], deren Aufgabe es ist, über Rechtsstreitigkeiten zu entscheiden und die Einhaltung der Gesetze sicherzustellen\""}, {"kategorie": "", "text": "Gerichte spielen eine zentrale Rolle im [[Rechtsstaat]], indem sie [[Gesetze]] anwenden, Streitfälle klären und im [[Strafrecht]] über Schuld oder Unschuld urteilen"}, {"kategorie": "", "text": "Sie arbeiten unabhängig von der [[Exekutive]] ([[Regierung]]) und der [[Legislative]] ([[Parlament]]), um eine gerechte und unparteiische [[Rechtsprechung]] zu gewährleisten"}, {"kategorie": "", "text": "Gerichte sind in ihrer Urteilsfindung unabhängig und nur an die Gesetze gebunden. [[Richter]] sind nicht an Weisungen gebunden, und ihre Entscheidungen basieren auf den geltenden [[Rechtsnormen]]"}, {"kategorie": "", "text": "Die [[Bezirksgerichte]] sind für geringfügigere Zivil- und Strafsachen zuständig, während die [[Landesgerichte]] schwerere Fälle behandeln. Der [[Oberste]] Gerichtshof (OGH) ist die höchste Instanz in Zivil- und Strafsachen und sorgt für eine einheitliche Rechtsprechung"}, {"kategorie": "", "text": "[[Zivilgerichte]] befassen sich mit Streitigkeiten zwischen Privatpersonen oder Unternehmen, (z. B. bei Vertragsfragen oder Erbschaftsangelegenheiten), und [[Strafgerichte]] entscheiden über Vergehen und Verbrechen (indem sie über Schuld oder Unschuld sowie über die Strafen urteilen)"}, {"kategorie": "", "text": "[[Verwaltungsgerichte]] überprüfen Verwaltungsakte und Entscheidungen staatlicher Behörden (z. B. in Steuer- oder Asylfragen)"}, {"kategorie": "", "text": "Die Gerichte sind in ihrem jeweiligen Zuständigkeitsbereich tätig. Sie entscheiden über Fälle, die ihnen im Rahmen der geltenden Gesetze vorgelegt werden. Sie garantieren die Rechtssicherheit und den Zugang zu einem fairen Verfahren für alle Bürger."}]'::jsonb, ''),
  ('gerichtsorganisation', 'Gerichtsorganisation', '', '', '', '', 'Gerichtsorganisation', '[{"kategorie": "pol.", "text": "\"Struktur und Funktionsweise des [[Justizsystems]], das in verschiedene Gerichtsebenen unterteilt ist. Diese Ebenen sind darauf ausgelegt, unterschiedliche Arten von Rechtsstreitigkeiten effizient zu bearbeiten und die [[Rechtsprechung]] nach festgelegten Verfahren sicherzustellen\""}, {"kategorie": "", "text": "Gerichtsstruktur in Österreich: (i) [[Ordentliche]] Gerichte: Diese befassen sich mit zivilrechtlichen und strafrechtlichen Angelegenheiten. Sie sind hierarchisch gegliedert und umfassen folgende Ebenen: [[Bezirksgerichte]] (die unterste Instanz. Sie sind für kleinere Zivil- und Strafsachen zuständig, beispielsweise für Streitigkeiten mit geringem Streitwert oder leichtere Vergehen), [[Landesgerichte]] (diese Gerichte entscheiden über Berufungen gegen Urteile der Bezirksgerichte und behandeln schwerwiegendere Zivil- und Strafsachen), [[Oberlandesgerichte]] (diese Gerichte fungieren als Berufungsinstanzen für die Landesgerichte und behandeln komplexe, meist berufungsfähige Fälle), [[Oberster]] Gerichtshof (OGH): Der OGH ist die höchste Instanz in Zivil- und Strafsachen. Er sorgt für die Einheitlichkeit der [[Rechtsprechung]] und entscheidet über Rechtsfragen von grundsätzlicher Bedeutung;  (ii) [[Verwaltungsgerichte]]: Diese Gerichte überprüfen Verwaltungsakte und Entscheidungen von Verwaltungsbehörden auf ihre Rechtmäßigkeit. Es gibt: Verwaltungsgerichte der Länder ([[Landesverwaltungsgerichte]]: Sie sind für die Überprüfung der Verwaltung auf Länderebene zuständig), [[Bundesverwaltungsgericht]] (prüft Entscheidungen von Bundesbehörden), [[Bundesfinanzgericht]] (zuständig für Streitfälle in Steuerangelegenheiten);  (iii) [[Verfassungsgerichtshof]] (VfGH): Der Verfassungsgerichtshof prüft die Verfassungsmäßigkeit von Gesetzen und Verordnungen. Er kann Gesetze aufheben, wenn sie der österreichischen Verfassung widersprechen"}, {"kategorie": "", "text": "Die Gerichtsorganisation stellt sicher, dass die [[Gewaltenteilung]] und der Zugang zu einem fairen und rechtmäßigen Verfahren in Österreich gewahrt bleiben. Sie schafft ein System, in dem Bürger ihre Rechte verteidigen und Gerechtigkeit durch unabhängige Gerichte finden können​."}]'::jsonb, ''),
  ('justizsystem', 'Justizsystem', '', '', '', '', 'Justizsystem', '[{"kategorie": "", "text": "Die Judikative ist dafür verantwortlich, Gesetze anzuwenden und über Streitfälle zu entscheiden. Ihre Hauptaufgabe ist es, die Einhaltung der Gesetze zu überwachen und sicherzustellen, dass diese korrekt interpretiert und durchgesetzt werden"}, {"kategorie": "", "text": "Die Justiz ist in Österreich unabhängig von der [[Regierung]] und dem Parlament. Das bedeutet, dass [[Gerichte]] und [[Richter]] nicht in ihrer Entscheidungsfindung durch andere Staatsorgane beeinflusst werden dürfen. Diese Unabhängigkeit ist durch die österreichische [[Bundesverfassung]] garantiert"}, {"kategorie": "", "text": "Die Judikative spielt eine zentrale Rolle in der [[Rechtsstaatlichkeit]] Österreichs, indem sie sicherstellt, dass die Gesetze des Landes korrekt angewendet werden und die Rechte der Bürger geschützt sind"}, {"kategorie": "", "text": "Zusammengefasst ist die Judikative in Österreich das System der [[Gerichte]], das für die Durchsetzung der Gesetze, die [[Rechtsprechung]] und den Schutz der Verfassung verantwortlich ist​."}]'::jsonb, ''),
  ('justiz', 'Justiz', '', '', '', '', 'Justiz', '[{"kategorie": "", "text": "Die Judikative ist dafür verantwortlich, Gesetze anzuwenden und über Streitfälle zu entscheiden. Ihre Hauptaufgabe ist es, die Einhaltung der Gesetze zu überwachen und sicherzustellen, dass diese korrekt interpretiert und durchgesetzt werden"}, {"kategorie": "", "text": "Die Justiz ist in Österreich unabhängig von der [[Regierung]] und dem Parlament. Das bedeutet, dass [[Gerichte]] und [[Richter]] nicht in ihrer Entscheidungsfindung durch andere Staatsorgane beeinflusst werden dürfen. Diese Unabhängigkeit ist durch die österreichische [[Bundesverfassung]] garantiert"}, {"kategorie": "", "text": "Die Judikative spielt eine zentrale Rolle in der [[Rechtsstaatlichkeit]] Österreichs, indem sie sicherstellt, dass die Gesetze des Landes korrekt angewendet werden und die Rechte der Bürger geschützt sind"}, {"kategorie": "", "text": "Zusammengefasst ist die Judikative in Österreich das System der [[Gerichte]], das für die Durchsetzung der Gesetze, die [[Rechtsprechung]] und den Schutz der Verfassung verantwortlich ist​."}]'::jsonb, ''),
  ('judikative', 'Judikative', '', '', '', '', 'Judikative', '[{"kategorie": "pol.", "text": "\"die rechtsprechende Gewalt des Staates und eine der drei Säulen der [[Gewaltenteilung]] neben der [[Legislative]] (gesetzgebende Gewalt) und der [[Exekutive]] (ausführende Gewalt)\""}, {"kategorie": "", "text": "Die Judikative ist dafür verantwortlich, Gesetze anzuwenden und über Streitfälle zu entscheiden. Ihre Hauptaufgabe ist es, die Einhaltung der Gesetze zu überwachen und sicherzustellen, dass diese korrekt interpretiert und durchgesetzt werden"}, {"kategorie": "", "text": "Die Justiz ist in Österreich unabhängig von der [[Regierung]] und dem Parlament. Das bedeutet, dass [[Gerichte]] und [[Richter]] nicht in ihrer Entscheidungsfindung durch andere Staatsorgane beeinflusst werden dürfen. Diese Unabhängigkeit ist durch die österreichische [[Bundesverfassung]] garantiert"}, {"kategorie": "", "text": "Die Judikative spielt eine zentrale Rolle in der [[Rechtsstaatlichkeit]] Österreichs, indem sie sicherstellt, dass die Gesetze des Landes korrekt angewendet werden und die Rechte der Bürger geschützt sind"}, {"kategorie": "", "text": "Zusammengefasst ist die Judikative in Österreich das System der [[Gerichte]], das für die Durchsetzung der Gesetze, die [[Rechtsprechung]] und den Schutz der Verfassung verantwortlich ist​."}]'::jsonb, ''),
  ('voik', 'Voik', '', '', '', '', 'Volk', '[{"kategorie": "", "text": "Das österreichische Volk bildet die Grundlage der staatlichen Souveränität und hat als Träger der [[Staatsgewalt]] ein Mitspracherecht in der Gestaltung des politischen und rechtlichen Systems des Landes"}, {"kategorie": "", "text": "Das österreichische Volk ist durch gemeinsame Rechte und Pflichten, eine gemeinsame [[Verfassung]] und die Teilnahme am demokratischen Leben des Staates verbunden"}, {"kategorie": "", "text": "Merkmale des österreichischen Volkes:  (i) [[Staatsbürgerschaft]]: Zum österreichischen Volk gehören alle Personen, die die österreichische Staatsbürgerschaft besitzen. Diese Staatsbürgerschaft ist Grundlage für die politischen Rechte und Pflichten, die dem Einzelnen als Mitglied der österreichischen Gemeinschaft zukommen;  (ii) Träger der Staatsgewalt: In der österreichischen [[Verfassung]] (Bundes-Verfassungsgesetz, Art. 1) ist festgelegt, dass alle [[Staatsgewalt]] vom [[Volk]] ausgeht. Dies bedeutet, dass das österreichische Volk über Wahlen und direktdemokratische Instrumente wie [[Volksabstimmungen]], [[Volksbefragungen]] und [[Volksbegehren]] an der politischen Willensbildung teilnimmt;  (iii) Demokratische Rechte und Pflichten: Staatsbürgerinnen und Staatsbürger haben das Recht, an Wahlen auf kommunaler, Landes- und Bundesebene teilzunehmen, sowie das Recht auf freie Meinungsäußerung, Versammlungsfreiheit und Mitbestimmung im Rahmen der demokratischen Ordnung. Gleichzeitig haben sie Pflichten, wie die Steuerzahlung und, für Männer, die Pflicht zum Wehr- oder Zivildienst (sofern nicht ausgesetzt);  (iv) Vielfalt und Integration: Das österreichische Volk ist ethnisch, kulturell und sprachlich vielfältig. Österreich fördert die Integration und das Zusammenleben verschiedener Volksgruppen und Minderheiten, etwa der slowenischen, kroatischen und ungarischen Minderheiten, die in der Verfassung anerkannt sind;  (v) Identität und Zugehörigkeit: Das österreichische Volk teilt eine gemeinsame kulturelle und historische Identität, die durch die Sprache, Traditionen und das Bewusstsein der gemeinsamen Geschichte geprägt ist. Diese Identität bildet die Grundlage für das nationale Zusammengehörigkeitsgefühl und den sozialen Zusammenhalt"}, {"kategorie": "", "text": "Das österreichische Volk ist somit die zentrale Grundlage des österreichischen Staates und verkörpert dessen demokratische und rechtsstaatliche Prinzipien. Es bestimmt durch seine Willensäußerungen und demokratische Beteiligung die politische Ausrichtung des Landes."}]'::jsonb, ''),
  ('gewoitnteilung', 'Gewoitnteilung', '', '', '', '', 'Gewaltenteilung', '[{"kategorie": "pol.", "text": "\"fundamentales Prinzip der österreichischen [[Verfassung]], das die staatliche Macht auf drei getrennte Gewalten aufteilt: die [[Legislative]] (gesetzgebende Gewalt), die [[Exekutive]] (ausführende Gewalt) und die [[Judikative]] (rechtsprechende Gewalt)\""}, {"kategorie": "", "text": "Diese Trennung dient dazu, Machtmissbrauch zu verhindern und die Freiheit und Rechte der [[Bürger]] zu schützen, indem jede Gewalt die andere kontrolliert und in ihrer Funktion beschränkt"}, {"kategorie": "", "text": "Die Gewaltenteilung in Österreich schafft ein System der Checks and Balances, in dem die Gewalten einander kontrollieren und ausgleichen"}, {"kategorie": "", "text": "Sie garantiert, dass kein Organ oder Amtsträger unbeschränkte Macht erlangen kann, wodurch der [[Rechtsstaat]] und die demokratischen Prinzipien gesichert werden"}, {"kategorie": "", "text": "Dieses Prinzip der Gewaltenteilung ist fest in der österreichischen [[Bundesverfassung]] verankert und bildet eine Grundlage für den Schutz der [[Bürgerrechte]] und der [[demokratischen]] Ordnung im Land."}]'::jsonb, ''),
  ('bundespraesident', 'Bundespräsident', '', '', '', '', 'Bundespräsident', '[{"kategorie": "pol.", "text": "\"Staatsoberhaupt der Republik Österreich, das den Staat sowohl nach innen als auch nach außen repräsentiert\""}, {"kategorie": "", "text": "Der Bundespräsident wird direkt vom Volk für eine Amtszeit von sechs Jahren gewählt und kann einmal wiedergewählt werden. Er hat hauptsächlich repräsentative Aufgaben, verfügt aber auch über einige wichtige Kompetenzen innerhalb des politischen Systems"}, {"kategorie": "", "text": "Aufgaben und Befugnisse des österreichischen Bundespräsidenten:  (i) Repräsentative Funktion: Als höchstes Staatsoberhaupt vertritt der Bundespräsident Österreich im Ausland und bei offiziellen Anlässen. Er symbolisiert die Einheit und Kontinuität des Staates;  (ii) Ernennung und Entlassung der [[Bundesregierung]]: Der Bundespräsident ernennt den [[Bundeskanzler]] und auf dessen Vorschlag die Mitglieder der [[Bundesregierung]]. Er hat theoretisch das Recht, die Bundesregierung auch ohne vorherige Abstimmung im Parlament zu entlassen, was jedoch selten genutzt wird;  (iii) Auflösung des [[Nationalrats]]: Der Bundespräsident hat das Recht, den Nationalrat aufzulösen und damit Neuwahlen einzuleiten. Diese Befugnis wurde in der [[Zweiten]] Republik bislang nicht genutzt;  (iv) Oberbefehl über das [[Bundesheer]]: Der Bundespräsident ist der formale Oberbefehlshaber des österreichischen Bundesheeres, was ihm eine symbolische, aber auch bedeutende Position in der Verteidigungsstruktur verleiht;  (v) Begnadigungsrecht: Er hat das Recht, Strafverurteilte zu begnadigen oder Strafen zu erlassen. Diese Macht wird in Ausnahmefällen und meist im Rahmen humanitärer Überlegungen ausgeübt;  (vi) Abschluss und Ratifikation von Staatsverträgen: Der Bundespräsident schließt Staatsverträge ab und ratifiziert sie, wobei die meisten internationalen Verträge zuvor die Zustimmung des Nationalrats erfordern;  (vii) Repräsentation der Verfassung: Der Bundespräsident steht für die [[Verfassung]] und [[Rechtsstaatlichkeit]] und spielt eine wichtige Rolle in Krisenzeiten, indem er das Vertrauen in die demokratischen Institutionen wahrt;  (vii) Rolle und Bedeutung im politischen System: In der Praxis übt der österreichische Bundespräsident seine Kompetenzen meist zurückhaltend aus, da das politische System auf einer [[parlamentarischen]] Demokratie basiert. Dies bedeutet, dass die [[Regierung]] und der [[Nationalrat]] die Hauptverantwortung für politische Entscheidungen tragen. Dennoch ist der Bundespräsident eine wichtige Integrationsfigur, die im Bedarfsfall stabilisierend wirken und in Krisenfällen politische Neutralität bewahren kann."}]'::jsonb, ''),
  ('bundesregiirung', 'Bundesregiirung', '', '', '', '', 'Bundesregierung', '[{"kategorie": "pol.", "text": "\"zentrales Exekutivorgan auf Bundesebene, verantwortlich für die Führung der Staatsgeschäfte und die Umsetzung der Gesetze, die vom [[Parlament]] beschlossen werden\""}, {"kategorie": "", "text": "Sie besteht aus dem [[Bundeskanzler]], dem [[Vizekanzler]] und den [[Bundesministern]], die jeweils bestimmte Ressorts leiten, sowie den [[Staatssekretären]], welche den [[Bundesministern]] unterstellt sind und diese bei der Erfüllung deren Aufgaben unterstützen"}, {"kategorie": "", "text": "Die Bundesregierung vertritt die politische Leitung und koordiniert die Verwaltung des Staates"}, {"kategorie": "", "text": "Die Bundesregierung wird formell vom [[Bundespräsidenten]] ernannt"}, {"kategorie": "", "text": "Der Bundeskanzler wird in der Regel von der stärksten Partei im [[Nationalrat]] gestellt, und die [[Minister]] werden auf Vorschlag des Kanzlers vom Bundespräsidenten bestellt"}, {"kategorie": "", "text": "Die Regierung ist dem Nationalrat gegenüber verantwortlich, und der Nationalrat kann der Regierung durch ein [[Misstrauensvotum]] das Vertrauen entziehen"}, {"kategorie": "", "text": "In Österreich sind [[Koalitionsregierungen]] aufgrund des proportionalen Wahlsystems häufig, da selten eine einzelne Partei die Mehrheit der Sitze im Nationalrat erreicht. Daher arbeitet die Bundesregierung oft als Koalition aus zwei oder mehr Parteien, die sich auf ein gemeinsames Regierungsprogramm einigen."}]'::jsonb, ''),
  ('bueagarechte', 'Büagarechte', '', '', '', '', 'Bürgerrechte', '[{"kategorie": "", "text": "Die Bürgerrechte sind in der österreichischen [[Bundesverfassung]] sowie in internationalen Abkommen wie der [[Europäischen]] Menschenrechtskonvention (EMRK) verankert, die für Österreich verbindlich ist"}, {"kategorie": "", "text": "Diese Rechte bilden die Basis des [[Rechtsstaates]] und sichern wesentliche Freiheiten und Gleichbehandlung für alle Bürgerinnen und Bürger"}, {"kategorie": "", "text": "Wichtige Bürgerrechte in Österreich:  (i) Recht auf Leben und körperliche Unversehrtheit: Der Staat schützt das Leben und die körperliche Integrität jedes Menschen. Eingriffe sind nur unter sehr strengen Bedingungen zulässig;  (ii) Meinungs-, Presse- und Informationsfreiheit: Jeder hat das Recht, seine Meinung frei zu äußern und Informationen zu empfangen und zu verbreiten. Die Medienfreiheit wird dabei besonders geschützt;  (iii) Gleichheit vor dem Gesetz: Alle Menschen sind vor dem Gesetz gleich und haben Anspruch auf denselben rechtlichen Schutz, unabhängig von Geschlecht, Herkunft, Religion oder sozialem Status;  (iv) Religions- und Glaubensfreiheit: Menschen dürfen ihre Religion oder Weltanschauung frei wählen, praktizieren und verbreiten, ohne Diskriminierung oder Einschränkung durch den Staat;  (v) Versammlungs- und Vereinigungsfreiheit: Das Recht, sich friedlich zu versammeln und Vereine oder Gruppen zu gründen, ist ein zentrales demokratisches Grundrecht;  (vi) Recht auf Privat- und Familienleben: Jeder hat Anspruch auf Schutz seines Privat- und Familienlebens sowie der eigenen Wohnung und Korrespondenz;  (vii) Eigentumsrecht: Der Schutz des Eigentums ist garantiert, und Enteignungen dürfen nur im öffentlichen Interesse und mit fairer Entschädigung erfolgen;  (viii) Recht auf ein faires Verfahren: [[Bürger]] haben das Recht auf ein gerechtes, öffentliches und zügiges Verfahren vor einem unabhängigen Gericht"}, {"kategorie": "", "text": "Die Bürgerrechte haben in Österreich Verfassungsrang und können vor den [[Gerichten]], einschließlich des [[Verfassungsgerichtshofs]], eingeklagt werden. Sie bilden das Fundament des demokratischen [[Rechtsstaats]] und garantieren die Freiheit und Sicherheit der Bürger vor willkürlichen Eingriffen des Staates. Die Einhaltung der Grundrechte ist eine zentrale Aufgabe aller staatlichen Institutionen und wird durch unabhängige Gerichte überwacht."}]'::jsonb, ''),
  ('grundrechte', 'Grundrechte', '', '', '', '', 'Grundrechte', '[{"kategorie": "", "text": "Die Grundrechte sind in der österreichischen [[Bundesverfassung]] sowie in internationalen Abkommen wie der [[Europäischen]] Menschenrechtskonvention (EMRK) verankert, die für Österreich verbindlich ist"}, {"kategorie": "", "text": "Diese Rechte bilden die Basis des [[Rechtsstaates]] und sichern wesentliche Freiheiten und Gleichbehandlung für alle Bürgerinnen und Bürger"}, {"kategorie": "", "text": "Wichtige Grundrechte in Österreich:  (i) Recht auf Leben und körperliche Unversehrtheit: Der Staat schützt das Leben und die körperliche Integrität jedes Menschen. Eingriffe sind nur unter sehr strengen Bedingungen zulässig;  (ii) Meinungs-, Presse- und Informationsfreiheit: Jeder hat das Recht, seine Meinung frei zu äußern und Informationen zu empfangen und zu verbreiten. Die Medienfreiheit wird dabei besonders geschützt;  (iii) Gleichheit vor dem Gesetz: Alle Menschen sind vor dem Gesetz gleich und haben Anspruch auf denselben rechtlichen Schutz, unabhängig von Geschlecht, Herkunft, Religion oder sozialem Status;  (iv) Religions- und Glaubensfreiheit: Menschen dürfen ihre Religion oder Weltanschauung frei wählen, praktizieren und verbreiten, ohne Diskriminierung oder Einschränkung durch den Staat;  (v) Versammlungs- und Vereinigungsfreiheit: Das Recht, sich friedlich zu versammeln und Vereine oder Gruppen zu gründen, ist ein zentrales demokratisches Grundrecht;  (vi) Recht auf Privat- und Familienleben: Jeder hat Anspruch auf Schutz seines Privat- und Familienlebens sowie der eigenen Wohnung und Korrespondenz;  (vii) \nEigentumsrecht: Der Schutz des Eigentums ist garantiert, und Enteignungen dürfen nur im öffentlichen Interesse und mit fairer Entschädigung erfolgen;  (viii) Recht auf ein faires Verfahren: [[Bürger]] haben das Recht auf ein gerechtes, öffentliches und zügiges Verfahren vor einem unabhängigen Gericht"}, {"kategorie": "", "text": "Die Grundrechte haben in Österreich Verfassungsrang und können vor den [[Gerichten]], einschließlich des [[Verfassungsgerichtshofs]], eingeklagt werden. Sie bilden das Fundament des demokratischen [[Rechtsstaats]] und garantieren die Freiheit und Sicherheit der Bürger vor willkürlichen Eingriffen des Staates. Die Einhaltung der Grundrechte ist eine zentrale Aufgabe aller staatlichen Institutionen und wird durch unabhängige Gerichte überwacht."}]'::jsonb, ''),
  ('rechtsschdood', 'Rechtsschdood', '', '', '', '', 'Rechtsstaat', '[{"kategorie": "pol.", "text": "\"Staat, in dem das Handeln aller staatlichen Institutionen an Gesetze gebunden ist und das Recht die Grundlage der gesamten Staatsordnung bildet\""}, {"kategorie": "", "text": "In einem Rechtsstaat gibt es klare Regeln, die sowohl für die [[Bürger]] als auch für den [[Staat]] gelten und deren Einhaltung durch unabhängige [[Gerichte]] überwacht wird"}, {"kategorie": "", "text": "[[Rechtsstaatlichkeit]] sichert die Gleichheit vor dem Gesetz, die Rechts- und Verfahrenssicherheit und den Schutz der Grund- und Freiheitsrechte"}, {"kategorie": "", "text": "In einem Rechtsstaat wie Österreich wird die [[Rechtsstaatlichkeit]] durch die [[Verfassung]] und die unabhängige Gerichtsbarkeit gesichert"}, {"kategorie": "", "text": "Das Rechtsstaatsprinzip schützt die Bürger vor willkürlichen Entscheidungen des Staates und garantiert, dass staatliches Handeln im Rahmen der Gesetze und zugunsten der Gerechtigkeit erfolgt."}]'::jsonb, ''),
  ('rechtsschdoodlichkeit', 'Rechtsschdoodlichkeit', '', '', '', '', 'Rechtsstaatlichkeit', '[{"kategorie": "pol.", "text": "\"verfassungsrechtliches Prinzip, welches gewährleistet, dass alle staatlichen Institutionen und Behörden an die Gesetze gebunden sind und im Rahmen des Rechts handeln müssen\""}, {"kategorie": "", "text": "Dieses Prinzip stellt sicher, dass staatliches Handeln vorhersehbar, kontrollierbar und gerecht ist"}, {"kategorie": "", "text": "Rechtsstaatlichkeit ist ein fundamentales Prinzip der österreichischen [[Bundesverfassung]] und dient dem Schutz der [[Bürgerrechte]] sowie der Sicherstellung von Freiheit und Gerechtigkeit"}, {"kategorie": "", "text": "Wesentliche Elemente der Rechtsstaatlichkeit in Österreich:  (i) [[Legalitätsprinzip]]: Nach Artikel 18 der österreichischen [[Bundesverfassung]] ist die gesamte Verwaltung an die Gesetze gebunden. Dies bedeutet, dass staatliche Entscheidungen und Handlungen immer eine gesetzliche Grundlage haben müssen;  (ii) [[Gewaltenteilung]]: Die Rechtsstaatlichkeit basiert auf der Trennung der drei Gewalten – [[Legislative]] (Gesetzgebung), [[Exekutive]] (Verwaltung) und [[Judikative]] (Gerichte). Diese Trennung verhindert Machtkonzentration und sichert die unabhängige Kontrolle staatlicher Organe;  (iii) [[Grund-]] und Freiheitsrechte: Rechtsstaatlichkeit schützt die [[Bürgerrechte]] wie Meinungsfreiheit, Gleichheit vor dem Gesetz und das Recht auf ein faires Verfahren. Diese Rechte sind in der [[Verfassung]] und internationalen Abkommen verankert und gewährleisten individuelle Freiheiten und Schutz vor staatlichen Eingriffen;  (iv) Unabhängige [[Justiz]]: Die [[Gerichte]] in Österreich sind unabhängig und nur an die Gesetze gebunden. Sie garantieren die Kontrolle des staatlichen Handelns und bieten den Bürgerinnen und Bürgern Schutz vor willkürlichen Entscheidungen der Exekutive und Legislative;  (v) Rechtsschutz und gerichtliche Kontrolle: Die Bürger haben das Recht, gegen staatliche Entscheidungen vorzugehen und rechtlichen Schutz durch unabhängige Gerichte zu suchen. Verfassungsrechtliche Fragen können vom [[Verfassungsgerichtshof]] geprüft werden, der Gesetze auf ihre Vereinbarkeit mit der Verfassung kontrolliert"}, {"kategorie": "", "text": "Insgesamt stellt die Rechtsstaatlichkeit sicher, dass Österreich als demokratischer [[Rechtsstaat]] organisiert ist, in dem das staatliche Handeln stets im Rahmen des Rechts geschieht und die Rechte der Bürgerinnen und Bürger geschützt sind."}]'::jsonb, ''),
  ('voiksobschdimmung', 'Voiksobschdimmung', '', '', '', '', 'Volksabstimmung', '[{"kategorie": "pol.", "text": "\"direktdemokratisches Verfahren in Österreich, bei dem die Bevölkerung über eine konkrete [[Gesetzesvorlage]] oder eine verfassungsrechtliche Änderung abstimmt\""}, {"kategorie": "", "text": "Im Unterschied zur [[Volksbefragung]] ist das Ergebnis einer Volksabstimmung rechtlich bindend, sodass die Entscheidung der Bevölkerung zwingend umgesetzt werden muss"}, {"kategorie": "", "text": "Eine Volksabstimmung findet statt, wenn der [[Nationalrat]] dies beschließt, insbesondere bei Verfassungsänderungen, die grundlegende Strukturprinzipien betreffen. Außerdem muss eine Volksabstimmung abgehalten werden, wenn das Amt des [[Bundespräsidenten]] vorzeitig endet und der Nationalrat die Neuwahl des Präsidenten ablehnt"}, {"kategorie": "", "text": "Das Ergebnis der Volksabstimmung ist für den Nationalrat und die [[Regierung]] bindend. Ein \"Ja\" oder \"Nein\" der Bevölkerung entscheidet direkt über die Annahme oder Ablehnung des jeweiligen [[Gesetzes]] oder Verfassungsentwurfs"}, {"kategorie": "", "text": "Die Abstimmung erfolgt landesweit und steht allen österreichischen Staatsbürgerinnen und Staatsbürgern, die wahlberechtigt sind, offen"}, {"kategorie": "", "text": "Zu den bekanntesten Volksabstimmungen in Österreich zählen die Volksabstimmung über den Beitritt zur Europäischen Union 1994 und die Volksabstimmung zur Inbetriebnahme des Kernkraftwerks Zwentendorf 1978. In beiden Fällen wurde das Ergebnis direkt umgesetzt"}, {"kategorie": "", "text": "Die Volksabstimmung stellt somit das stärkste direktdemokratische Instrument in Österreich dar und ermöglicht den Bürgern, über wesentliche politische und verfassungsrechtliche Fragen direkt zu entscheiden."}]'::jsonb, ''),
  ('voiksbegean', 'Voiksbegean', '', '', '', '', 'Volksbegehren', '[{"kategorie": "pol.", "text": "\"direktdemokratisches Mittel in Österreich, mit dem Bürgerinnen und Bürger den [[Nationalrat]] dazu auffordern können, sich mit einem bestimmten Gesetzesvorschlag oder politischen Anliegen zu beschäftigen\""}, {"kategorie": "", "text": "Es ermöglicht der Bevölkerung, auf die nationale Gesetzgebung Einfluss zu nehmen und politische Themen auf die Agenda zu setzen"}, {"kategorie": "", "text": "Ein Volksbegehren kann von jeder Bürgerin und jedem Bürger ab 16 Jahren initiiert werden. Für die Einleitung sind zunächst 8.401 Unterstützungserklärungen notwendig (entspricht einem Promille der Wahlberechtigten)"}, {"kategorie": "", "text": "Wenn ein Volksbegehren diese erste Hürde überschritten hat, folgt die sogenannte Eintragungswoche, in der alle wahlberechtigten Staatsbürger das Volksbegehren durch ihre Unterschrift unterstützen können"}, {"kategorie": "", "text": "Damit das Volksbegehren im [[Nationalrat]] behandelt werden muss, sind mindestens 100.000 gültige Unterschriften oder die Unterstützung von mindestens je einem Sechstel der Wahlberechtigten in drei Bundesländern notwendig"}, {"kategorie": "", "text": "Erreicht das Volksbegehren die erforderliche Anzahl an Unterschriften, ist der Nationalrat verpflichtet, das Anliegen in einer Sitzung zu beraten. Er muss jedoch nicht zwingend eine Gesetzesänderung vornehmen oder das Anliegen umsetzen; die Behandlung im Parlament ist jedoch sichergestellt"}, {"kategorie": "", "text": "Volksbegehren wurden in Österreich zu verschiedenen Themen eingeleitet, etwa zum Nichtraucherschutz, Klimaschutz oder gegen Atomkraft. Sie bieten der Bevölkerung eine Möglichkeit, politische Anliegen aktiv in die öffentliche Diskussion und den parlamentarischen Prozess einzubringen."}]'::jsonb, ''),
  ('voiksbefroogung', 'Voiksbefroogung', '', '', '', '', 'Volksbefragung', '[{"kategorie": "pol.", "text": "\"direktdemokratisches Instrument in Österreich, bei dem die Bevölkerung zu bestimmten politischen Fragen ihre Meinung abgeben kann\""}, {"kategorie": "", "text": "Im Gegensatz zu einer [[Volksabstimmung]] ist das Ergebnis einer Volksbefragung rechtlich nicht bindend und dient den politischen Entscheidungsträgern lediglich als Orientierungshilfe"}, {"kategorie": "", "text": "Volksbefragungen können auf Bundes-, Landes- oder Gemeindeebene durchgeführt werden und können von der Regierung oder den gesetzgebenden Körperschaften zu verschiedenen politischen oder gesellschaftlichen Themen initiiert werden. Auf Bundesebene bedarf es eines Beschlusses des [[Nationalrates]]"}, {"kategorie": "", "text": "Volksbefragungen wurden in Österreich unter anderem zu Fragen der Wehrpflicht (2013) oder zum Thema europäische Integration diskutiert und genutzt"}, {"kategorie": "", "text": "Volksbefragungen erfolgen nach denselben Prinzipien wie Wahlen. Die Bevölkerung hat dabei die Möglichkeit, ihre Stimme „Ja“ oder „Nein“ zu einer gestellten Frage abzugeben"}, {"kategorie": "", "text": "Volksbefragungen ermöglichen es der österreichischen Bevölkerung, ihre Meinung zu wichtigen politischen Fragen einzubringen, und sind ein Ausdruck der gelebten Demokratie in Österreich."}]'::jsonb, ''),
  ('legalitaetsprinzip', 'Legalitätsprinzip', '', '', '', '', 'Legalitätsprinzip', '[{"kategorie": "jur.", "text": "\"fundamentales Prinzip des österreichischen [[Rechtsstaats]], das besagt, dass die gesamte staatliche Verwaltung nur auf Grundlage der Gesetze handeln darf\""}, {"kategorie": "", "text": "Es ist in Artikel 18 der österreichischen Bundesverfassung verankert und stellt sicher, dass jede Handlung und Entscheidung der Verwaltung rechtlich begründet sein muss"}, {"kategorie": "", "text": "Die wesentlichen Aspekte des Legalitätsprinzips sind: (i) Gesetzesbindung: Alle [[Verwaltungsbehörden]] sind an die bestehenden Gesetze gebunden und dürfen nur im Rahmen der gesetzlichen Bestimmungen agieren. Dies verhindert willkürliches Verhalten und sichert die Einhaltung des Rechts;  (ii) [[Rechtsstaatlichkeit]]: Das Prinzip schützt die Bürgerinnen und Bürger vor ungerechtfertigten Eingriffen des [[Staates]] und garantiert, dass Verwaltungshandeln überprüfbar und gerecht ist;  (iii) [[Gewaltenteilung]]: Das Legalitätsprinzip unterstützt die Trennung zwischen [[Legislative]] (Gesetzgebung) und [[Exekutive]] (Verwaltung), indem es die [[Verwaltung]] an die von der Legislative beschlossenen Gesetze bindet"}, {"kategorie": "", "text": "Das Legalitätsprinzip stellt damit eine Grundlage für den Schutz der Bürgerrechte und die Transparenz des staatlichen Handelns in Österreich dar."}]'::jsonb, ''),
  ('vawoitung', 'Vawoitung', '', '', '', '', 'Verwaltung', '[{"kategorie": "pol.", "text": "\"Gesamtheit der staatlichen Einrichtungen und Tätigkeiten in Österreich, die Gesetze vollziehen und staatliche Aufgaben im Interesse der Öffentlichkeit wahrnehmen\""}, {"kategorie": "", "text": "Sie ist Teil der [[Exekutive]] und umfasst Aufgabenbereiche auf Bundes-, Landes- und Gemeindeebene: (i) Bundesverwaltung: Die Aufgaben werden im Namen des Bundes ausgeführt und umfassen Bereiche wie innere Sicherheit, Bildung, und Finanzen. Die Bundesverwaltung wird durch [[Ministerien]] und [[Bundesbehörden]] organisiert;  (ii) Landesverwaltung: Die Länder sind für die Vollziehung bestimmter eigener Angelegenheiten verantwortlich, etwa im Bereich des Schulwesens und der Raumplanung. Die Verwaltung erfolgt durch die [[Landesregierungen]] und -behörden;  (iii) Gemeindeebene: Die Gemeinden übernehmen lokale Verwaltungsaufgaben wie Meldewesen, Bauangelegenheiten und die örtliche Sicherheit"}, {"kategorie": "", "text": "Die Verwaltung arbeitet im Rahmen der Gesetze und wird durch die politischen Organe und [[Gerichte]] kontrolliert"}, {"kategorie": "", "text": "Die österreichische Verwaltung ist zudem vom Prinzip des [[Legalitätsprinzips]] geprägt, wonach alle Verwaltungsakte an die bestehenden Gesetze gebunden sind. Dieses Prinzip sichert eine gesetzeskonforme, transparente und rechtsstaatliche Verwaltung in Österreich."}]'::jsonb, ''),
  ('juliputsch', 'Juliputsch', '', '', '', '', 'Juliputsch', '[{"kategorie": "hist.", "text": "\"ein von den österreichischen Nationalsozialisten am 25. Juli 1934 initiierter, gescheiterter Putschversuch gegen die Regierung des [[Bundeskanzlers]] Engelbert Dollfuß in Österreich\""}, {"kategorie": "", "text": "Die Putschisten versuchten, die autoritäre Regierung des [[Ständestaats]] zu stürzen und das Land an das nationalsozialistische Deutschland anzuschließen, das damals bereits unter der Führung Adolf Hitlers stand"}, {"kategorie": "", "text": "Am 25. Juli drangen bewaffnete Nationalsozialisten in das Bundeskanzleramt in Wien ein und nahmen das Gebäude ein. Im Verlauf des Überfalls wurde Bundeskanzler [[Dollfuß]] tödlich verletzt"}, {"kategorie": "", "text": "Die Putschisten proklamierten eine neue, pro-nationalsozialistische Regierung, doch der Aufstand fand nur begrenzte Unterstützung in der Bevölkerung und wurde nach wenigen Tagen von der österreichischen Armee und Polizei niedergeschlagen"}, {"kategorie": "", "text": "Der Juliputsch führte zu einer verschärften politischen Situation in Österreich. Dollfuß'' Nachfolger, [[Kurt]] Schuschnigg, setzte den autoritären Kurs fort und versuchte, Österreichs Unabhängigkeit gegenüber dem nationalsozialistischen Deutschland zu bewahren"}, {"kategorie": "", "text": "Der Putschversuch verstärkte jedoch den Druck auf Österreich und trug letztlich zur schrittweisen Annäherung an das nationalsozialistische Regime bei, die 1938 im [[Anschluss]] an das [[Deutsche]] Reich mündete."}]'::jsonb, ''),
  ('monarch', 'Monarch', '', '', '', '', 'Monarch', '[{"kategorie": "hist.", "text": "\"Herrscher an der Spitze des Staates und über Jahrhunderte das zentrale Symbol der habsburgischen Macht und Autorität\""}, {"kategorie": "", "text": "Der österreichische Monarch, zunächst als [[Herzog]] und später als [[Kaiser]], besaß die höchste weltliche und in vielen Belangen auch geistliche Autorität. Unter den Habsburgern stieg Österreich ab dem Spätmittelalter zur führenden Macht im [[Heiligen]] Römischen Reich auf, und der österreichische Monarch prägte die Politik des Reiches entscheidend"}, {"kategorie": "", "text": "Ab 1804 führte der österreichische Monarch offiziell den Titel [[Kaiser]] von Österreich mit der Gründung des [[Kaiserreichs]] Österreich durch Kaiser [[Franz]] I., um die Souveränität Österreichs nach außen zu stärken"}, {"kategorie": "", "text": "Mit dem [[Österreichisch-Ungarischen]] Ausgleich 1867 wurde der Monarch gleichzeitig Kaiser von Österreich und [[König]] von Ungarn, womit er die [[Doppelmonarchie]] Österreich-Ungarn regierte. Dieser Ausgleich verlieh den beiden Reichsteilen weitgehende Autonomie, hielt aber die Macht beim Monarchen als übergreifender Herrscher beider Landesteile"}, {"kategorie": "", "text": "Der Monarch übte seine Macht durch die Kontrolle über Regierung, Militär und Verwaltung aus, wobei Persönlichkeiten wie Kaiser [[Franz]] Joseph I. symbolisch für die Stabilität und den Einfluss der Monarchie standen"}, {"kategorie": "", "text": "Die Monarchie endete 1918 nach dem [[Ersten]] Weltkrieg, als Kaiser [[Karl]] I. abdankte und Österreich zur Republik wurde."}]'::jsonb, ''),
  ('monarchii', 'Monarchii', '', '', '', '', 'Monarchie', '[{"kategorie": "hist.", "text": "\"über Jahrhunderte die zentrale Regierungsform in Österreich, in der ein [[Monarch]] – ursprünglich ein [[Herzog]], später ein [[Kaiser]] – an der Spitze des Staates stand und die oberste Entscheidungsgewalt ausübte\""}, {"kategorie": "", "text": "Die österreichische Monarchie entwickelte sich unter der Herrschaft des [[Hauses]] Habsburg, das ab dem 15. Jahrhundert eine dominante Rolle im [[Heiligen]] Römischen Reich einnahm und Österreich zum Mittelpunkt einer der mächtigsten Monarchien Europas machte"}, {"kategorie": "", "text": "Die österreichische Monarchie war zunächst Teil des Heiligen Römischen Reiches, bis dieses 1806 aufgelöst wurde. Daraufhin rief Kaiser [[Franz]] I. das [[Kaiserreich]] Österreich aus, das eine zentrale Rolle in der europäischen Politik spielte"}, {"kategorie": "", "text": "Mit dem [[Österreichisch-Ungarischen]] Ausgleich 1867 entstand die Donaumonarchie Österreich-Ungarn, eine Doppelmonarchie, in der Österreich und Ungarn weitgehende Autonomie genossen, jedoch unter einem gemeinsamen Kaiser standen. Kaiser [[Franz]] Joseph I. war eine prägende Figur dieser Zeit und verkörperte die Stabilität und den Glanz der [[Habsburgermonarchie]]"}, {"kategorie": "", "text": "Die Monarchie in Österreich endete 1918 mit dem Zusammenbruch Österreich-Ungarns nach dem [[Ersten]] Weltkrieg und der Abdankung Kaiser [[Karls]] I."}, {"kategorie": "", "text": "Österreich wurde zur Republik, und die Monarchie wurde offiziell abgeschafft. Die österreichische Monarchie hinterließ jedoch ein bedeutendes kulturelles und architektonisches Erbe und prägt das Land bis heute kulturell und historisch."}]'::jsonb, ''),
  ('laundschdaende', 'Laundschdände', '', '', '', '', 'Landstände', '[{"kategorie": "hist.", "text": "\"Versammlungen der Vertreter des Adels, der Geistlichkeit und später auch der städtischen Bürger in den einzelnen Territorien der [[Habsburgermonarchie]], wie etwa in den [[Herzogtümern]] Österreich, Steiermark, Kärnten und Tirol\""}, {"kategorie": "", "text": "Die Landstände bildeten die politische Interessenvertretung dieser gesellschaftlichen Gruppen gegenüber dem [[Landesfürsten]] und hatten bedeutenden Einfluss auf die Verwaltung und Gesetzgebung der jeweiligen Region"}, {"kategorie": "", "text": "Die Landstände verfügten über das Recht, Steuern zu bewilligen, und hatten Mitspracherechte bei militärischen Angelegenheiten sowie in gerichtlichen und administrativen Fragen"}, {"kategorie": "", "text": "In Krisenzeiten oder bei finanziellen Engpässen war der Landesfürst häufig auf die Unterstützung der Landstände angewiesen, da diese die notwendigen Mittel bewilligten. Im Gegenzug konnten die Landesstände Forderungen stellen und die Rechte und Freiheiten der Stände sichern"}, {"kategorie": "", "text": "Mit der Zentralisierungspolitik der [[Habsburger]] und insbesondere mit den Reformen von Kaiserin [[Maria]] Theresia und Kaiser [[Joseph]] II. im 18. Jahrhundert wurde die Macht der Landstände erheblich eingeschränkt. Dennoch blieben sie bis ins 19. Jahrhundert eine bedeutende regionale Instanz und prägten die politische Struktur in den habsburgischen [[Erblanden]]"}, {"kategorie": "", "text": "Die Landstände sind ein wichtiger Bestandteil der österreichischen Geschichte und zeigen die föderale Struktur der habsburgischen Herrschaft."}]'::jsonb, ''),
  ('laundesschdaende', 'Laundesschdände', '', '', '', '', 'Landesstände', '[{"kategorie": "hist.", "text": "\"Versammlungen der Vertreter des Adels, der Geistlichkeit und später auch der städtischen Bürger in den einzelnen Territorien der [[Habsburgermonarchie]], wie etwa in den [[Herzogtümern]] Österreich, Steiermark, Kärnten und Tirol\""}, {"kategorie": "", "text": "Die Landesstände bildeten die politische Interessenvertretung dieser gesellschaftlichen Gruppen gegenüber dem [[Landesfürsten]] und hatten bedeutenden Einfluss auf die Verwaltung und Gesetzgebung der jeweiligen Region"}, {"kategorie": "", "text": "Die Landesstände verfügten über das Recht, Steuern zu bewilligen, und hatten Mitspracherechte bei militärischen Angelegenheiten sowie in gerichtlichen und administrativen Fragen"}, {"kategorie": "", "text": "In Krisenzeiten oder bei finanziellen Engpässen war der Landesfürst häufig auf die Unterstützung der Landesstände angewiesen, da diese die notwendigen Mittel bewilligten. Im Gegenzug konnten die Landesstände Forderungen stellen und die Rechte und Freiheiten der Stände sichern"}, {"kategorie": "", "text": "Mit der Zentralisierungspolitik der [[Habsburger]] und insbesondere mit den Reformen von Kaiserin [[Maria]] Theresia und Kaiser [[Joseph]] II. im 18. Jahrhundert wurde die Macht der Landesstände erheblich eingeschränkt. Dennoch blieben sie bis ins 19. Jahrhundert eine bedeutende regionale Instanz und prägten die politische Struktur in den habsburgischen [[Erblanden]]"}, {"kategorie": "", "text": "Die Landesstände sind ein wichtiger Bestandteil der österreichischen Geschichte und zeigen die föderale Struktur der habsburgischen Herrschaft."}]'::jsonb, ''),
  ('laundesfueast', 'Laundesfüast', '', '', '', '', 'Landesfürst', '[{"kategorie": "hist.", "text": "\"souveräner Herrscher eines bestimmten Territoriums oder einer [[Erblandschaft]] innerhalb der [[Habsburgermonarchie]]\""}, {"kategorie": "", "text": "Der Begriff umfasst die jeweiligen Fürsten, die direkt über ihre Gebiete herrschten, wie [[Herzöge]], [[Erzherzöge]] oder [[Könige]]"}, {"kategorie": "", "text": "In den österreichischen [[Erblanden]], zu denen unter anderem die [[Herzogtümer]] Österreich, Steiermark, Kärnten und Tirol gehörten, waren die [[Habsburger]] die Landesfürsten, die als Herrscher dieser Gebiete eigene Rechte und Privilegien wahrnahmen"}, {"kategorie": "", "text": "Der Landesfürst hatte das höchste politische, militärische und gerichtliche Amt in seinem Land und war verantwortlich für die Verwaltung und Verteidigung des Territoriums. Diese Herrschaft wurde als Landesherrschaft bezeichnet und umfasste neben rechtlicher und administrativer Kontrolle auch das Recht, Steuern zu erheben und Truppen aufzustellen"}, {"kategorie": "", "text": "Der Titel „Landesfürst“ betonte die enge Beziehung zwischen dem Herrscher und seinem Land und stellte ihn als direkten „obersten Herrn“ dar, der gegenüber den lokalen Ständen die höchste Autorität ausübte"}, {"kategorie": "", "text": "In Österreich blieb der Titel des Landesfürsten symbolisch auch nach dem Ende des [[Heiligen]] Römischen Reiches und der Errichtung des [[Kaiserreichs]] Österreich bestehen und wurde bis zum Ende der [[Monarchie]] 1918 für die [[Habsburger]] verwendet."}]'::jsonb, ''),
  ('laundgroofschoft', 'Laundgroofschoft', '', '', '', '', 'Landgrafschaft', '[{"kategorie": "hist.", "text": "\"Territorium im [[Heiligen]] Römischen Reich, das von einem Landgrafen regiert wurde\""}, {"kategorie": "", "text": "Der Titel des Landgrafen und die Einrichtung von Landgrafschaften entstanden im Mittelalter, um die Macht und Autonomie dieser Gebiete innerhalb des Reiches zu stärken"}, {"kategorie": "", "text": "Ein [[Landgraf]] war direkt dem [[Kaiser]] unterstellt und hatte dadurch eine relativ unabhängige Stellung, ohne einem [[Herzog]] oder anderen regionalen [[Fürsten]] untergeordnet zu sein"}, {"kategorie": "", "text": "Landgrafschaften wurden oft in Grenzregionen eingerichtet, um die Kontrolle und Verteidigung des Reiches zu gewährleisten. Im Gegensatz zu [[Herzogtümern]], die häufig aus traditionellen Stammesgebieten bestanden, waren Landgrafschaften eher geografisch festgelegte Verwaltungsgebiete. Sie waren mit allen wichtigen Herrschaftsrechten ausgestattet, darunter Gerichtsbarkeit, Steuererhebung und militärische Befugnisse"}, {"kategorie": "", "text": "Bekannte Landgrafschaften waren z.B. die Landgrafschaft Thüringen und die Landgrafschaft Hessen. Diese Territorien spielten eine bedeutende Rolle in der politischen Struktur des Reiches, da sie durch ihre direkte kaiserliche Unterstellung eine gewisse Eigenständigkeit besaßen und oft bedeutende politische und militärische Machtzentren bildeten"}, {"kategorie": "", "text": "In Österreich gab es im Mittelalter keine eigenständigen Landgrafschaften im gleichen Sinne wie in Deutschland. Allerdings wurden bestimmte Gebiete und Titel im Rahmen der habsburgischen Herrschaftsstruktur als „Landgrafschaften“ bezeichnet, um die territorialen Ansprüche und Rechte der [[Habsburger]] innerhalb des Heiligen Römischen Reiches zu betonen."}]'::jsonb, ''),
  ('laundgroof', 'Laundgroof', '', '', '', '', 'Landgraf', '[{"kategorie": "hist.", "text": "\"hoher Adelstitel im [[Heiligen]] Römischen Reich, der den Herrscher über eine [[Landgrafschaft]] bezeichnete\""}, {"kategorie": "", "text": "Der Titel entstand im Mittelalter und sollte ursprünglich das direkte Verhältnis des Landgrafen zum [[Kaiser]] oder [[König]] betonen, wodurch er weniger abhängig von anderen, meist benachbarten [[Fürsten]] war"}, {"kategorie": "", "text": "Der Landgraf stand in der Hierarchie unter einem [[Herzog]], jedoch über [[Grafen]] und [[Baronen]], und besaß sowohl militärische als auch gerichtliche und administrative Machtbefugnisse innerhalb seiner Landgrafschaft"}, {"kategorie": "", "text": "Im Gegensatz zu Herzögen, die oft über historische Stammesgebiete herrschten, regierten Landgrafen über geografisch definierte Territorien und hatten meist die Aufgabe, Grenzregionen zu sichern und zu verwalten"}, {"kategorie": "", "text": "Bekannte Landgrafschaften gab es im heutigen Deutschland, wie etwa in Hessen und Thüringen. Der Titel des Landgrafen verlor mit der Zentralisierung der Staatsgewalt im Laufe der Neuzeit an Bedeutung, blieb jedoch ein wichtiges historisches Element in der Territorialgeschichte des [[Heiligen]] Römischen Reiches"}, {"kategorie": "", "text": "In Österreich gab es im Mittelalter keine eigenständigen Landgrafschaften im gleichen Sinne wie in Deutschland. Allerdings wurden bestimmte Gebiete und Titel im Rahmen der habsburgischen Herrschaftsstruktur als à„Landgrafschaften“ bezeichnet, um die territorialen Ansprüche und Rechte der [[Habsburger]] innerhalb des Heiligen Römischen Reiches zu betonen."}]'::jsonb, ''),
  ('weihbischof', 'Weihbischof', '', '', '', '', 'Weihbischof', '[{"kategorie": "rel.", "text": "\"Bischof, der einen [[Diözesanbischof]] in seiner [[Diözese]] unterstützt, jedoch selbst nicht das Oberhaupt einer eigenen Diözese ist\""}, {"kategorie": "", "text": "Weihbischöfe übernehmen zahlreiche liturgische und seelsorgerische Aufgaben und unterstützen den Diözesanbischof in der Verwaltung und Organisation der Diözese, besonders in großen [[Bistümern]] oder in Zeiten hoher Arbeitsbelastung"}, {"kategorie": "", "text": "Zu den Aufgaben eines Weihbischofs gehören unter anderem die Feier von Firmungen, Weihen und andere Sakramentenspendungen"}, {"kategorie": "", "text": "Weihbischöfe werden, wie alle [[Bischöfe]], vom Papst ernannt und tragen den Titel einer historischen oder inaktiven Diözese (Titularbistum), die heute nicht mehr existiert"}, {"kategorie": "", "text": "Der Weihbischof ist damit bischöflich geweiht und hat alle sakramentalen Vollmachten eines Bischofs, ist jedoch in seiner Funktion an den Diözesanbischof gebunden und übernimmt keine eigenständige Leitung einer Diözese"}, {"kategorie": "", "text": "In Österreich gibt es in einigen Diözesen Weihbischöfe, die durch ihre Unterstützung die seelsorgerische Betreuung und die liturgische Präsenz in der gesamten Diözese sicherstellen."}]'::jsonb, ''),
  ('dioezesanbischof', 'Diözesanbischof', '', '', '', '', 'Diözesanbischof', '[{"kategorie": "rel.", "text": "\"leitender [[Bischof]] einer [[Diözese]], der die oberste Verantwortung für die seelsorgerische, administrative und spirituelle Führung des kirchlichen Lebens in seinem [[Bistum]] trägt\""}, {"kategorie": "", "text": "Er ist dafür zuständig, die katholische Lehre zu wahren, Sakramente zu spenden, Priester zu weihen und die pastoralen Aktivitäten der Diözese zu leiten"}, {"kategorie": "", "text": "Der Diözesanbischof steht dabei über den Priestern und Diakonen seiner Diözese und vertritt die Diözese gegenüber der übergeordneten Kirchenleitung, insbesondere gegenüber der Bischofskonferenz und dem Papst"}, {"kategorie": "", "text": "In der katholischen Kirche wird ein Diözesanbischof vom Papst ernannt und in sein Amt eingeführt. Er hat die Aufgabe, das kirchliche und spirituelle Leben zu fördern, die Anliegen der Gläubigen zu vertreten und die Pfarreien seiner Diözese zu beaufsichtigen"}, {"kategorie": "", "text": "Der Diözesanbischof kann in seiner Arbeit von [[Weihbischöfen]] unterstützt werden und steht in größeren Diözesen häufig an der Spitze eines Seelsorgeteams und kirchlicher Verwaltungsstrukturen"}, {"kategorie": "", "text": "In Österreich gibt es neun Diözesanbischöfe, darunter die Bischöfe von Wien, Salzburg, Graz-Seckau und Linz, die jeweils eigenständige Diözesen leiten und das katholische Leben in ihrer Region prägen."}]'::jsonb, ''),
  ('diakon', 'Diakon', '', '', '', '', 'Diakon', '[{"kategorie": "rel.", "text": "\"Geistlicher in der katholischen, orthodoxen und einigen evangelischen Kirchen, der zur Ausübung bestimmter kirchlicher Dienste geweiht ist\""}, {"kategorie": "", "text": "Der Diakon gehört zum dreistufigen Weiheamt der Kirche, das aus Diakon, Priester und [[Bischof]] besteht. Seine Hauptaufgaben liegen in der Verkündigung des Evangeliums, der Caritas (Nächstenliebe) und der Liturgie"}, {"kategorie": "", "text": "Diakone können in verschiedenen Bereichen der Seelsorge tätig sein, wie etwa in der Unterstützung von Bedürftigen, Krankenbesuchen, Taufvorbereitungen und der Predigt. Sie dürfen Taufen spenden, Trauungen leiten und bei Gottesdiensten assistieren, haben jedoch keine Vollmacht zur Eucharistiefeier oder zur Absolution (Beichte), die Priestern und Bischöfen vorbehalten sind"}, {"kategorie": "", "text": "Es gibt zwei Arten von Diakonen in der katholischen Kirche: (i) Übergangsdiakone (Männer, die sich im letzten Schritt der Ausbildung zum Priesteramt befinden) und (ii) Ständige Diakone (Männer, die als Diakone im Amt bleiben; sie können verheiratet sein und sind oft auch in der Gemeindearbeit tätig)"}, {"kategorie": "", "text": "Diakone sind eine wichtige Unterstützung in der Gemeindeseelsorge und tragen durch ihren Dienst zur Stärkung und Förderung der kirchlichen Gemeinschaft bei."}]'::jsonb, ''),
  ('dioezeesn', 'Diözeesn', '', '', '', '', 'Diözese', '[{"kategorie": "rel.", "text": "\"Verwaltungsgebiet der katholischen Kirche, das von einem Bischof geleitet wird und die seelsorgerische Betreuung der Gläubigen innerhalb eines bestimmten geographischen Gebiets organisiert\""}, {"kategorie": "", "text": "In Österreich ist eine Diözese die zentrale kirchliche Einheit, die für die Organisation und Verwaltung von Pfarreien und kirchlichen Aktivitäten verantwortlich ist"}, {"kategorie": "", "text": "Österreich ist in neun Diözesen unterteilt, darunter die [[Erzdiözese]] Wien als bedeutendste. Jede Diözese wird von einem [[Bischof]] oder, im Fall der Erzdiözese Wien, von einem [[Erzbischof]] geleitet, der für die spirituelle Führung, den priesterlichen Nachwuchs und die ordnungsgemäße Durchführung der Sakramente verantwortlich ist"}, {"kategorie": "", "text": "Weitere bedeutende Diözesen sind z.B. die Diözesen Graz-Seckau, Linz und Salzburg, wobei Salzburg als Erzdiözese zugleich eine eigene Kirchenprovinz bildet"}, {"kategorie": "", "text": "Die Diözesen in Österreich sind wichtige religiöse und soziale Institutionen, die auch in Bildung und Wohlfahrt tätig sind und eine zentrale Rolle im kirchlichen Leben des Landes spielen."}]'::jsonb, ''),
  ('bischofsschdoob', 'Bischofsschdoob', '', '', '', '', 'Bischofsstab', '[{"kategorie": "", "text": "Der Stab ist oben oft in Form einer Krümme oder Spirale gestaltet, die an einen Hirtenstab erinnert und symbolisch die Funktion des Bischofs als „Hirten“ seiner Gemeinde und seiner Diözese betont"}, {"kategorie": "", "text": "Der Bischofsstab wird bei feierlichen Anlässen wie Gottesdiensten, Weihen und Prozessionen getragen und unterstreicht die Verantwortung des Bischofs, die Gläubigen zu leiten, zu beschützen und zu betreuen"}, {"kategorie": "", "text": "Der Stab steht dabei für Führung und Unterstützung, ähnlich wie ein Hirte seine Herde führt. In der Gestaltung ist der Bischofsstab oft kunstvoll verziert und kann aus wertvollen Materialien bestehen, um die Würde und Bedeutung des Amtes zu repräsentieren."}]'::jsonb, ''),
  ('mitra', 'Mitra', '', '', '', '', 'Mitra', '[{"kategorie": "rel.", "text": "\"festliche, hohe Kopfbedeckung eines Bischofs in der katholischen, orthodoxen und anglikanischen Kirche, die als Zeichen seines Amtes und seiner geistlichen Autorität dient\""}, {"kategorie": "", "text": "Sie besteht aus zwei spitz zulaufenden Teilen, die vorn und hinten hochgezogen sind und so die Form einer doppelten Spitze bilden. Hinten an der Mitra hängen zwei Bänder, die sogenannten „Infuln“"}, {"kategorie": "", "text": "Die Mitra wird traditionell bei liturgischen Feiern wie Gottesdiensten, Firmungen oder Prozessionen getragen und zeigt die besondere Stellung des Trägers. Sie symbolisiert die Verantwortung des Bischofs für seine Diözese und die Verbindung zu seinem apostolischen Auftrag"}, {"kategorie": "", "text": "Die Mitra ist oft kunstvoll gestaltet und kann je nach Rang und Anlass einfach oder aufwendig verziert sein."}]'::jsonb, ''),
  ('metropolit', 'Metropolit', '', '', '', '', 'Metropolit', '[{"kategorie": "rel.", "text": "\"Erzbischof der katholischen Kirche, der eine übergeordnete Leitungsfunktion innerhalb einer Kirchenprovinz innehat und für die Organisation und Aufsicht der zugehörigen [[Diözesen]] zuständig ist\""}, {"kategorie": "", "text": "In Österreich ist der [[Erzbischof]] von Wien zugleich Metropolit der Kirchenprovinz Wien, zu der neben dem [[Erzbistum]] Wien auch die [[Diözesen]] St. Pölten und Eisenstadt gehören"}, {"kategorie": "", "text": "Der Wiener Metropolit hat das Recht und die Aufgabe, die Bischöfe dieser Diözesen in bestimmten Fragen zu unterstützen und zu beaufsichtigen, beispielsweise in Fragen der kirchlichen Disziplin"}, {"kategorie": "", "text": "Zudem repräsentiert der Metropolit die Kirchenprovinz und spielt eine zentrale Rolle bei der Ernennung und Einführung neuer [[Bischöfe]] innerhalb seiner Kirchenprovinz"}, {"kategorie": "", "text": "In der katholischen Hierarchie ist der Metropolit von Wien somit eine Schlüsselperson und ein bedeutendes geistliches Oberhaupt für die Region Ostösterreich."}]'::jsonb, ''),
  ('eazbistum', 'Eazbistum', '', '', '', '', 'Eazbistum', '[{"kategorie": "rel.", "text": "\"wichtige kirchliche Verwaltungseinheit der katholischen Kirche, die von einem [[Erzbischof]] geleitet wird und oft übergeordnete Funktion für eine Gruppe von Diözesen in einer Region hat\""}, {"kategorie": "", "text": "Das Erzbistum Wien ist das zentrale Erzbistum in Österreich und umfasst die Stadt Wien sowie Teile Niederösterreichs"}, {"kategorie": "", "text": "Das Erzbistum wurde 1469 als Bistum gegründet und 1722 zum Erzbistum erhoben. Seitdem ist der Erzbischof von Wien zugleich [[Metropolit]] der Kirchenprovinz Wien, die neben dem Erzbistum Wien auch die Diözesen St. Pölten und Eisenstadt umfasst"}, {"kategorie": "", "text": "Das Erzbistum Wien spielt eine bedeutende Rolle in der katholischen Kirche Österreichs und hatte historisch großen Einfluss auf die religiöse, kulturelle und politische Entwicklung des Landes"}, {"kategorie": "", "text": "Es ist bis heute ein wichtiges Zentrum des österreichischen Katholizismus und einflussreich in gesellschaftlichen und sozialen Belangen."}]'::jsonb, ''),
  ('eazdioezeesn', 'Eazdiözeesn', '', '', '', '', 'Erzdiözese', '[{"kategorie": "rel.", "text": "\" kirchliche Verwaltungseinheit der katholischen Kirche, die von einem [[Erzbischof]] geleitet wird und oft eine zentrale Rolle in der kirchlichen Hierarchie einer Region einnimmt\""}, {"kategorie": "", "text": "Die Erzdiözese Wien ist eine der bedeutendsten Erzdiözesen in Österreich und umfasst die Stadt Wien sowie große Teile des Bundeslandes Niederösterreich"}, {"kategorie": "", "text": "Die Erzdiözese Wien wurde 1469 von Papst Paul II. auf Bitten Kaiser [[Friedrichs]] III. gegründet und 1722 von Papst Innozenz XIII. zum Erzbistum erhoben. Seitdem ist der Wiener Erzbischof nicht nur geistliches Oberhaupt der Region, sondern auch [[Metropolit]] der Kirchenprovinz Wien, zu der auch die Diözesen St. Pölten und Eisenstadt gehören"}, {"kategorie": "", "text": "Historisch spielte die Erzdiözese Wien eine zentrale Rolle in der religiösen, kulturellen und politischen Entwicklung Österreichs und engagierte sich stark in der Bildung und Sozialarbeit"}, {"kategorie": "", "text": "Bis heute ist die Erzdiözese Wien ein wichtiges Zentrum des österreichischen Katholizismus und einflussreich in Fragen der Sozialpolitik und kirchlichen Organisation im Land."}]'::jsonb, ''),
  ('eazbischof', 'Eazbischof', '', '', '', '', 'Erzbischof', '[{"kategorie": "rel.", "text": "\"hoher katholischer Geistlicher, der über eine Erzdiözese herrscht und oft auch eine führende Rolle innerhalb der Kirche einer Region hat\""}, {"kategorie": "", "text": "Historisch gesehen spielten Erzbischöfe in Österreich eine bedeutende Rolle, da sie sowohl geistliche als auch weltliche Macht ausübten. Besonders hervorzuheben ist der Erzbischof von Salzburg, der als Fürsterzbischof ein eigenständiges Fürstentum regierte und zugleich eine führende kirchliche Rolle im [[Heiligen]] Römischen Reich innehatte"}, {"kategorie": "", "text": "Diese Erzbischöfe besaßen umfangreiche Ländereien, politische Privilegien und waren Mitglieder der Reichsfürstenversammlung, wodurch sie Einfluss auf die Reichspolitik hatten. Sie konnten eigene Steuern erheben, Münzen prägen und waren für die Rechtsprechung in ihren Territorien zuständig. Auch die Erzbischöfe von Wien gewannen später an Bedeutung, insbesondere nach der Errichtung der Erzdiözese Wien im 18. Jahrhundert"}, {"kategorie": "", "text": "Erzbischöfe in Österreich waren nicht nur kirchliche Würdenträger, sondern auch starke politische Akteure, die sowohl in kirchlichen als auch weltlichen Angelegenheiten eine wichtige Machtposition innehatten."}]'::jsonb, ''),
  ('adeliger', 'Adeliger', '', '', '', '', 'Adeliger', '[{"kategorie": "hist.", "text": "\"Mitglied des gesellschaftlichen Standes in Österreich, der durch Titel, Privilegien und oft großen Landbesitz ausgezeichnet war und eine besondere Rolle in der politischen, militärischen und kulturellen Struktur des Landes spielte\""}, {"kategorie": "", "text": "Der österreichische Adel setzte sich aus verschiedenen Rängen zusammen, darunter [[Herzöge]], [[Fürsten]], [[Grafen]] und [[Freiherren]], und hatte oft engen Einfluss auf die Herrschaft des [[Hauses]] Habsburg"}, {"kategorie": "", "text": "Nach dem Ende des [[Heiligen]] Römischen Reiches und der Gründung des [[Kaiserreichs]] Österreich behielt der [[Adel]] zunächst seine privilegierte Stellung"}, {"kategorie": "", "text": "Durch die Aufhebung der Adelsprivilegien 1919 nach dem Ende der [[Monarchie]] wurde der Adel jedoch offiziell abgeschafft. Adelstitel durften nur noch als Namensbestandteile geführt werden, ohne besondere Rechte oder gesellschaftliche Vorzüge"}, {"kategorie": "", "text": "Der österreichische Adel blieb jedoch kulturell und historisch bedeutend und prägte das gesellschaftliche Leben des Landes weiterhin auf andere Weise."}]'::jsonb, ''),
  ('reichsschdaend', 'Reichsschdänd', '', '', '', '', 'Reichsstände', '[{"kategorie": "hist.", "text": "\"herrschende Elitegruppen im [[Heiligen]] Römischen Reich, die direkt dem [[Kaiser]] unterstellt waren und im [[Reichstag]] politische Mitbestimmungsrechte hatten\""}, {"kategorie": "", "text": "Die Reichsstände umfassten: (i) [[Kurfürsten]] (wahlberechtigte [[Fürsten]] für die Kaiserwahl),  (ii) weltliche und geistliche Fürsten (wie [[Herzöge]], [[Bischöfe]] und Äbte mit eigenen Gebieten),  (iii) freie Reichsstädte – Städte mit direkter Kaiserunterstellung und besonderen Rechten"}, {"kategorie": "", "text": "Die Reichsstände schränkten die Macht des Kaisers ein und prägten den föderalen Charakter des Reiches."}]'::jsonb, ''),
  ('reichsfueast', 'Reichsfüast', '', '', '', '', 'Reichsfürst', '[{"kategorie": "hist.", "text": "\"Adeliger mit dem Rang eines [[Fürsten]], der direkt dem [[Kaiser]] unterstellt war und damit eine besondere Stellung innerhalb der [[Reichsstände]] einnahm\""}, {"kategorie": "", "text": "In Österreich und seinen angrenzenden Regionen bezeichnete „Reichsfürst“ Fürsten, die sowohl politische als auch territoriale Macht besaßen und Reichslehen führten, also Gebiete, die ihnen unmittelbar vom Kaiser verliehen worden waren"}, {"kategorie": "", "text": "Reichsfürsten konnten weltliche Herrscher, wie [[Herzöge]] oder [[Landgrafen]], sein oder geistliche Würdenträger, wie die [[Erzbischöfe]] von Salzburg oder Bischöfe von Passau, die ebenfalls als Reichsfürsten galten"}, {"kategorie": "", "text": "Diese Reichsfürsten hatten das Recht, im [[Reichstag]] zu sitzen und an Reichsentscheidungen mitzuwirken, was ihnen erhebliche politische Macht verlieh. Sie waren „reichsunmittelbar“, das heißt, sie standen direkt unter dem Kaiser und nicht unter einem anderen Landesherren"}, {"kategorie": "", "text": "Für die österreichischen [[Habsburger]] war der Titel eines Reichsfürsten besonders bedeutsam, da er den Inhabern innerhalb des Reichs eine Vorrangstellung einräumte und die Machtbasis der habsburgischen Herrschaft festigte"}, {"kategorie": "", "text": "Die Habsburger selbst waren als Kaiser oft die höchsten „Reichsfürsten“ und nutzten ihre Position, um die österreichischen Ländereien und die eigenen Machtansprüche im Reich zu stärken und zu sichern."}]'::jsonb, ''),
  ('kiachnfueast', 'Kiachnfüast', '', '', '', '', 'Kirchenfürst', '[{"kategorie": "hist.", "text": "\"hochrangiger Geistlicher, der zugleich weltliche Macht und Einfluss besitzt, wie beispielsweise ein Erzbischof, Bischof oder Abt mit fürstlichem Rang\""}, {"kategorie": "", "text": "Der Begriff umfasst besonders jene geistlichen Würdenträger, die in früheren Jahrhunderten als [[Reichsfürsten]] galten und eigene Gebiete regierten, darunter wichtige Persönlichkeiten wie der [[Erzbischof]] von Salzburg oder der Bischof von Passau"}, {"kategorie": "", "text": "Diese Kirchenfürsten hatten im [[Heiligen]] Römischen Reich und später in den habsburgischen [[Erblanden]] bedeutenden politischen und gesellschaftlichen Einfluss. Sie vereinten geistliche und weltliche Macht, leiteten große Besitztümer und waren oft direkte Vasallen des [[Kaisers]]. Ihre Position verschaffte ihnen Sitz und Stimme im Reichstag und Einfluss auf kaiserliche Entscheidungen"}, {"kategorie": "", "text": "In Österreich besaßen Kirchenfürsten wie die Erzbischöfe von Salzburg – die ein eigenes Fürsterzbistum regierten – lange Zeit weitgehende Autonomie und waren wichtige Akteure im Machtgefüge des Reichs. Sie konnten Kriege führen, eigene Münzen prägen und verwalteten bedeutende Ländereien, wodurch sie eine zentrale Rolle in der österreichischen und mitteleuropäischen Geschichte spielten."}]'::jsonb, ''),
  ('grofschoft', 'Grofschoft', '', '', '', '', 'Grafschaft', '[{"kategorie": "hist.", "text": "\"historisches Territorium, das von einem Grafen verwaltet wurde und Teil des mittelalterlichen Lehnswesens im [[Heiligen]] Römischen Reich war\""}, {"kategorie": "", "text": "Grafen waren hochrangige Adlige, die im Auftrag des [[Kaisers]] oder [[Königs]] bestimmte Landstriche verwalteten und über regionale Gerichts- und Verwaltungsrechte verfügten"}, {"kategorie": "", "text": "Grafschaften standen in der Hierarchie unter [[Herzogtümern]] und [[Markgrafschaften]] und hatten begrenzte Selbstständigkeit innerhalb der größeren politischen Strukturen"}, {"kategorie": "", "text": "In Österreich bestanden verschiedene Grafschaften, die oft eine strategische oder wirtschaftliche Bedeutung hatten. Diese Gebiete waren Teil der feudalen Struktur des mittelalterlichen Reichs und häufig eng mit mächtigen Adelsfamilien verbunden, wie den [[Babenbergern]] und später den [[Habsburgern]]"}, {"kategorie": "", "text": "Grafschaften waren häufig kleinere Gebiete als Herzogtümer, und ihr Graf war dem Herzog, Markgrafen oder Kaiser direkt verpflichtet"}, {"kategorie": "", "text": "Während der Habsburgerherrschaft gingen viele Grafschaften in größeren politischen Einheiten auf, besonders als die österreichischen [[Erblande]] zu einem vereinten Herrschaftsgebiet zusammengefasst wurden"}, {"kategorie": "", "text": "Grafschaften blieben dennoch als Verwaltungseinheiten und Titel bestehen und spielten in der Struktur des [[Habsburgerreichs]] eine Rolle, bis das Feudalsystem nach und nach abgeschafft wurde."}]'::jsonb, ''),
  ('kaisa', 'Kaisa', '', '', '', '', 'Kaiser', '[{"kategorie": "hist.", "text": "\"höchster monarchischer Titel in der Rangordnung der Herrscher, welcher das Oberhaupt eines [[Kaisertums]] oder Imperiums bezeichnet\""}, {"kategorie": "", "text": "Der Titel wird in der Regel mit einem großen und oft multinationalen Reich in Verbindung gebracht, das über mehrere [[Königreiche]] und [[Fürstentümer]] hinausgeht"}, {"kategorie": "", "text": "Ein Kaiser steht über einem [[König]] und herrscht oft über ein weitreichendes Territorium oder mehrere Völker. Der Begriff leitet sich vom lateinischen Wort \"Caesar\" ab, dem Titel der römischen Herrscher"}, {"kategorie": "", "text": "Kaisertitel werden in den meisten Fällen durch [[Erbfolge]] weitergegeben, ähnlich wie bei Königen. Kaiserliche Dynastien, wie die [[Habsburger]] in Österreich, spielten eine zentrale Rolle in der Geschichte ihrer Reiche"}, {"kategorie": "", "text": "Historisch wurde der Kaiser als eine Art göttlich legitimiertes Oberhaupt angesehen, das über den anderen [[Monarchen]] steht, insbesondere im [[Heiligen]] Römischen Reich"}, {"kategorie": "", "text": "In vielen Fällen hatten Kaiser nicht nur weltliche Macht, sondern auch religiöse Autorität. So betrachtete sich der römisch-deutsche Kaiser als weltlicher Beschützer des Christentums, ähnlich wie der byzantinische Kaiser"}, {"kategorie": "", "text": "In Österreich war der Kaiser seit 1804 das Oberhaupt des [[Kaisertums]] Österreich, das von [[Franz]] II. gegründet wurde, nachdem er die [[Kaiserkrone]] des [[Heiligen]] Römischen Reiches niedergelegt hatte. Franz II. nahm den Titel [[Franz I., Kaiser von Österreich]] an und begründete die habsburgische Kaiserlinie in Österreich, die bis zum Ende der Monarchie 1918 bestand."}]'::jsonb, ''),
  ('kaisakrone', 'Kaisakrone', '', '', '', '', 'Kaiserkrone', '[{"kategorie": "hist.", "text": "\"Symbol für die höchste monarchische Macht und Autorität eines [[Kaisers]]\""}, {"kategorie": "", "text": "Sie steht als [[Insignie]] für die Herrschaft des [[Kaisers]] über ein [[Kaiserreich]] oder Imperium. Ähnlich wie die [[Königskrone]] für einen [[König]] symbolisiert die Kaiserkrone den Anspruch auf umfassende Macht und Herrschaft, oft über mehrere Königreiche oder Völker"}, {"kategorie": "", "text": "Historisch diente die Kaiserkrone als Zeichen der Legitimation und Autorität eines Kaisers und wurde bei feierlichen Anlässen wie Krönungen oder Staatszeremonien getragen"}, {"kategorie": "", "text": "In der Geschichte Österreichs spielte die [[Österreichische]] Kaiserkrone (auch [[Rudolfskrone]] genannt) eine bedeutende Rolle. Die Rudolfskrone (die Privatkrone Kaiser [[Rudolfs]] II., die für diesen im Jahr 1602 angefertigt wurde) wurde bei Ausrufung des [[Kaisertums]] Österreich durchà Franz II im Jahre 1804 als [[österreichische]] Kaiserkrone  bestimmt"}, {"kategorie": "", "text": "Nachdem er die [[Kaiserkrone]] des [[Heiligen]] Römischen Reiches niedergelegt hatte, nahm [[Franz]] II. den Titel [[Franz I., Kaiser von Österreich]] an und begründete die habsburgische Kaiserlinie in Österreich, die bis zum Ende der [[Monarchie]] 1918 bestand"}, {"kategorie": "", "text": "Die Krone war Teil der [[habsburgischen]] Reichsinsignien und wurde bei offiziellen Anlässen verwendet, um die Herrschaft des [[Kaisers]] darzustellen"}, {"kategorie": "", "text": "In der Wiener [[Schatzkammer]] der Hofburg kann die Krone heute besichtigt werden, wo sie als zentrales Stück der kaiserlichen [[Insignien]] ausgestellt ist. Sie ist ein bedeutendes Symbol für das [[Kaisertum]] Österreich und die lange Herrschaft der [[Habsburgerdynastie]]."}]'::jsonb, ''),
  ('restauration', 'Restauration', '', '', '', '', 'Restauration', '[{"kategorie": "hist.", "text": "\"historische Phase, in der nach revolutionären Umwälzungen oder politischen Veränderungen die alte Ordnung oder das frühere politische System wiederhergestellt wird\""}, {"kategorie": "", "text": "Es geht dabei häufig um die Wiedereinsetzung von [[Monarchien]] oder traditionellen Herrschaftsformen, die durch Revolutionen oder Kriege vorübergehend gestürzt wurden"}, {"kategorie": "", "text": "Der Begriff ist eng mit der Zeit nach dem [[Wiener]] Kongress (1814–1815) verbunden, als die europäischen Mächte versuchten, die alte monarchische Ordnung nach den [[Napoleonischen]] Kriegen wiederherzustellen"}, {"kategorie": "", "text": "Der österreichische Staatsmann Fürst Klemens von [[Metternich]] war eine der Schlüsselfiguren der [[Restauration]] in Europa. Er spielte eine entscheidende Rolle beim [[Wiener]] Kongress und verfolgte eine strikte konservative Politik, die darauf abzielte, revolutionäre Tendenzen zu unterdrücken und die alte monarchische Ordnung aufrechtzuerhalten"}, {"kategorie": "", "text": "Der Wiener Kongress führte zur Schaffung des [[Deutschen]] Bundes, einem lockeren Zusammenschluss der deutschen Staaten unter der Vorherrschaft Österreichs. Auch hier wurde versucht, die revolutionären Bestrebungen einzudämmen und die Fürstenhäuser zu stärken."}]'::jsonb, ''),
  ('mettanich', 'Mettanich', '', '', '', '', 'Metternich', '[{"kategorie": "", "text": "Metternich war vor allem während der Zeit der [[Restauration]] nach den [[Napoleonischen]] Kriegen und im Rahmen des [[Wiener]] Kongresses (1814–1815) von entscheidender Bedeutung. Er prägte die konservative, monarchisch geprägte Politik Europas und setzte sich für die Aufrechterhaltung der alten Ordnung und die Unterdrückung revolutionärer Bewegungen ein\""}, {"kategorie": "", "text": "Metternich wurde 1773 in eine einflussreiche Adelsfamilie geboren und trat früh in den diplomatischen Dienst ein. Er arbeitete zunächst als Gesandter in verschiedenen europäischen Höfen, darunter in Sachsen, Preußen und Frankreich, wo er diplomatische Erfahrungen sammelte"}, {"kategorie": "", "text": "Im Jahr 1809 wurde Metternich zum österreichischen Außenminister ernannt und spielte eine Schlüsselrolle in der diplomatischen Neuordnung Europas nach dem Ende der [[Napoleonischen]] Herrschaft. 1821 wurde er zusätzlich zum Staatskanzler Österreichs ernannt und blieb bis zu seiner Entlassung 1848 einer der einflussreichsten Politiker der [[Habsburgermonarchie]]"}, {"kategorie": "", "text": "Der Wiener Kongress war der Höhepunkt von Metternichs politischer Karriere. Er war der Hauptorganisator dieses internationalen Treffens, das nach dem Sturz Napoleons einberufen wurde, um die politischen Verhältnisse in Europa neu zu ordnen. Metternich setzte sich erfolgreich für die Wiederherstellung der alten monarchischen Ordnung und für das Prinzip des Gleichgewichts der Mächte ein, um eine stabile europäische Friedensordnung zu gewährleisten"}, {"kategorie": "", "text": "Er schuf das nach ihm benannte \"Metternich-System\", das auf die Stabilität und den Erhalt der bestehenden Machtstrukturen setzte. Zentral hierfür waren die enge Zusammenarbeit der europäischen Großmächte (Österreich, Preußen, Russland, Großbritannien) und die Unterdrückung revolutionärer Bestrebungen durch Zensur, Überwachung und Polizei (siehe [[Metternichner Polizeistaat]])"}, {"kategorie": "", "text": "Metternichs konservative Politik geriet in den 1840er Jahren zunehmend unter Druck, als in vielen Teilen Europas revolutionäre Bewegungen erstarkten. Die [[Revolution]] von 1848, die in weiten Teilen Europas Aufstände gegen die alten monarchischen Strukturen auslöste, führte zu seinem Rücktritt und Exil. Metternich floh zunächst nach England und kehrte erst Jahre später nach Wien zurück."}]'::jsonb, ''),
  ('napoleon', 'Napoleon', '', '', '', '', 'Napoleon', '[{"kategorie": "", "text": "Er stieg nach der [[Französischen]] Revolution an die Macht, wurde 1804 Kaiser der Franzosen und führte zahlreiche militärische Kampagnen, die Europa über mehr als ein Jahrzehnt prägten. Für Österreich hatte Napoleon weitreichende Auswirkungen, sowohl territorial als auch politisch"}, {"kategorie": "", "text": "Von 1792 bis 1815 kämpfte Österreich in den sogenannten [[Koalitionskriegen]] (insgesamt sieben Koalitionen) fast durchgehend gegen Frankreich, wobei Napoleon ab 1799 die zentrale Figur in diesen Kriegen war. Österreich war stets eine der führenden Mächte in den antifranzösischen Koalitionen, die das Ziel hatten, die französische Expansion und Napoleons Einfluss einzudämmen"}, {"kategorie": "", "text": "Nach dem Aufstieg Napoleons als Militärbefehlshaber erlitt Österreich mehrere schwere Niederlagen, die das [[Habsburgerreich]] erheblich schwächten. Im [[Frieden]] von Campo Formio (1797) musste Österreich nach der Niederlage gegen Napoleon im Ersten Koalitionskrieg große Gebiete, darunter die österreichischen Niederlande und Gebiete in Norditalien, an Frankreich abtreten"}, {"kategorie": "", "text": "Eine der wichtigsten Schlachten, die Österreich gegen Napoleon verlor, war die [[Schlacht]] bei Austerlitz (2. Dezember 1805), auch bekannt als die [[Dreikaiserschlacht]]. In dieser entscheidenden Schlacht besiegte Napoleon die vereinigten Truppen von Österreich und Russland. Dieser Sieg führte zum Frieden von Pressburg, in dem Österreich Teile seines Territoriums abgeben musste, darunter Venetien und Tirol. Zudem festigte Napoleon seine Kontrolle über Teile Deutschlands und Italien, was Österreichs Einfluss in Mitteleuropa erheblich einschränkte"}, {"kategorie": "", "text": "Napoleon förderte die Gründung des [[Rheinbundes]] im Jahr 1806, einer Gruppe von deutschen Staaten, die sich von der österreichischen Oberhoheit lossagten und unter Napoleons Protektorat stellten. Dies führte unmittelbar zum Ende des [[Heiligen]] Römischen Reiches Deutscher Nation. Der österreichische Kaiser [[Franz]] II. legte 1806 die Krone des Heiligen Römischen Reiches nieder und erklärte das Reich für aufgelöst"}, {"kategorie": "", "text": "Fortan trug er den Titel \"[[Franz]] I., Kaiser von Österreich\", wodurch das [[Habsburgerreich]] als eigenständiges [[Kaisertum]] weiter bestand. Dieses Ereignis markierte das Ende der Jahrhunderte langen Habsburger Herrschaft über das Heilige Römische Reich und die Neuordnung Europas unter französischer Vorherrschaft"}, {"kategorie": "", "text": "Nach Jahren der militärischen Demütigungen und Gebietsverluste gelang es Österreich, die Anti-Napoleon-Koalitionen wieder anzuführen. In der [[Schlacht]] bei Leipzig (1813), auch als [[Völkerschlacht]] bekannt, kämpften österreichische Truppen unter der Führung von Fürst Karl Schwarzenberg in einer Allianz mit Russland, Preußen und Schweden gegen Napoleons Armee. Diese Schlacht führte zur Niederlage Napoleons und war ein Wendepunkt in den [[Napoleonischen]] Kriegen"}, {"kategorie": "", "text": "Nach Napoleons endgültiger Niederlage und der Unterzeichnung der [[Wiener]] Kongressbeschlüsse konnte Österreich einige verlorene Gebiete zurückerlangen, darunter Venetien und Teile Norditaliens. Es konsolidierte auch seine Position als führende Macht in Mitteleuropa, wenn auch nicht mehr in der Rolle des römisch-deutschen Kaisers, sondern als zentrale [[Monarchie]] im neu etablierten [[Deutschen]] Bund."}]'::jsonb, ''),
  ('rheinbund', 'Rheinbund', '', '', '', '', 'Rheinbund', '[{"kategorie": "hist.", "text": "\"Bündnis deutscher Staaten, das 1806 unter dem Einfluss von [[Napoleon]] Bonaparte gegründet wurde und bis 1813 bestand\""}, {"kategorie": "", "text": "Der Bund sollte die Machtbasis Napoleons in Mitteleuropa stärken und die französische Vorherrschaft über das Gebiet sichern. Er umfasste 16 deutsche [[Fürstentümer]] und [[Königreiche]], die sich von Frankreich Schutz versprachen und im Gegenzug ihre Unabhängigkeit vom [[Heiligen]] Römischen Reich erklärten"}, {"kategorie": "", "text": "Der Rheinbund führte damit zur Auflösung des [[Heiligen]] Römischen Reiches Deutscher Nation und stellte einen schweren Schlag für Österreich dar, das traditionell eine Führungsrolle im Reich innehatte"}, {"kategorie": "", "text": "Mit der Gründung des Rheinbundes sah sich Kaiser [[Franz]] II. von Habsburg gezwungen, die [[Kaiserkrone]] des Heiligen Römischen Reiches niederzulegen, und erklärte das Reich für aufgelöst. Damit verlor Österreich seine zentrale Stellung im Reich und musste sich verstärkt auf seine eigenen Gebiete konzentrieren"}, {"kategorie": "", "text": "Durch den Rheinbund büßte Österreich seinen Einfluss auf die deutschen Staaten ein, die sich nun unter französischem Schutz befanden und eng an Napoleon gebunden waren. Österreichs Macht und Einfluss in Mitteleuropa wurden erheblich geschwächt"}, {"kategorie": "", "text": "Nach der Niederlage Napoleons 1813 im Zuge der Befreiungskriege löste sich der Rheinbund auf, und Österreich spielte beim [[Wiener]] Kongress (1814–1815) eine führende Rolle bei der Neuordnung Europas. Der [[Deutsche]] Bund wurde als neuer, von Österreich dominierter Zusammenschluss der deutschen Staaten gegründet, um die Hegemonie Frankreichs zu verhindern und Österreichs Einfluss wiederherzustellen."}]'::jsonb, ''),
  ('koalitionskriag', 'Koalitionskriag', '', '', '', '', 'Koalitionskriege', '[{"kategorie": "hist.", "text": "\"Reihe militärischer Konflikte in Europa zwischen 1792 und 1815, in denen sich wechselnde europäische Bündnisse (Koalitionen) gegen das revolutionäre und später napoleonische Frankreich stellten\""}, {"kategorie": "", "text": "Insgesamt fanden sechs Koalitionskriege statt. Sie umfassten bedeutende Schlachten und hatten tiefgreifende Auswirkungen auf die politische und territoriale Ordnung Europas"}, {"kategorie": "", "text": "Für Österreich waren die Koalitionskriege besonders bedeutend, da das [[Habsburgerreich]] eine der führenden Mächte der antifranzösischen Koalitionen war. Die Konflikte hatten jedoch schwere Belastungen für Österreich zur Folge, sowohl wirtschaftlich als auch militärisch, und führten mehrmals zur territorialen Neuordnung des Landes und zu kurzfristigen Niederlagen"}, {"kategorie": "", "text": "Nach der Niederlage im Dritten Koalitionskrieg (1805) verlor Österreich beispielsweise das [[Heilige]] Römische Reich und wurde stattdessen zum [[Kaisertum]] Österreich umgeformt. Auch im Fünften Koalitionskrieg (1809) erlitt Österreich Niederlagen und musste weitere Gebietsverluste hinnehmen"}, {"kategorie": "", "text": "Nach der letzten Niederlage Napoleons in der Schlacht bei Waterloo 1815 wurde Frankreich besiegt, und der [[Wiener]] Kongress, der von Österreich mitorganisiert wurde, schuf eine neue europäische Ordnung. Diese sollte die Machtbalance in Europa wiederherstellen und den Frieden sichern, was letztlich zur Gründung des [[Deutschen]] Bundes führte, dessen Vorsitz Österreich übernahm."}]'::jsonb, ''),
  ('dreikaisaschlocht', 'Dreikaisaschlocht', '', '', '', '', 'Dreikaiserschlacht', '[{"kategorie": "hist.", "text": "\"Schlacht, welche am 2. Dezember 1805 nahe der mährischen Stadt Austerlitz (heute Slavkov u Brna in Tschechien) stattfand (auch bekannt als die [[Schlacht bei Austerlitz]])\""}, {"kategorie": "", "text": "In dieser Schlacht besiegte Napoleon Bonaparte die verbündeten Armeen des Russischen Zaren Alexander I. und des Österreichischen Kaisers [[Franz]] II. Die Schlacht gilt als eines der brillantesten militärischen Manöver Napoleons und markiert einen Höhepunkt seiner militärischen Karriere"}, {"kategorie": "", "text": "Die Schlacht bei Austerlitz war Teil des Dritten Koalitionskrieges (1805–1806), in dem Großbritannien, Russland, und Österreich ein Bündnis gegen das aufstrebende napoleonische Frankreich geschlossen hatten"}, {"kategorie": "", "text": "Napoleon hatte etwa 73.000 Soldaten zur Verfügung, während die alliierten Armeen, bestehend aus russischen und österreichischen Truppen, rund 85.000 Mann umfassten. Obwohl zahlenmäßig unterlegen, war die französische Armee besser organisiert, und Napoleon nutzte die geografischen Gegebenheiten und das Überraschungsmoment geschickt zu seinem Vorteil"}, {"kategorie": "", "text": "Napoleon täuschte eine Schwäche vor und zog seine Truppen so zurück, dass die Alliierten dachten, sie hätten einen strategischen Vorteil. Er lockte die gegnerischen Truppen in eine verwundbare Position, indem er den Pratzenberg, ein zentrales Plateau, zunächst aufgab. Die Alliierten nahmen den Köder und griffen diesen vermeintlichen Schwachpunkt an"}, {"kategorie": "", "text": "Napoleon nutzte daraufhin seine Reservetruppen und griff die Mitte der Alliierten auf dem Pratzenberg unerwartet an, durchbrach ihre Linien und spaltete die Koalitionsarmee in zwei Hälften"}, {"kategorie": "", "text": "Die französische Armee schlug die Alliierten zurück, und die Schlacht endete mit einer vernichtenden Niederlage für die russisch-österreichischen Truppen, die in Unordnung flohen. Die Alliierten verloren rund 36.000 Mann, darunter Tote, Verwundete und Gefangene, während die französischen Verluste auf etwa 9.000 Mann geschätzt werden"}, {"kategorie": "", "text": "Die Niederlage führte zur Auflösung der Dritten Koalition und zwang Österreich zum [[Frieden]] von Pressburg (26. Dezember 1805), wodurch Österreich erhebliche Gebiete und Einfluss verlor"}, {"kategorie": "", "text": "Das [[Heilige]] Römische Reich löste sich im folgenden Jahr (1806) auf, und Napoleon stieg zum unangefochtenen Herrscher über weite Teile Europas auf"}, {"kategorie": "", "text": "Zusammengefasst war die Schlacht bei Austerlitz ein entscheidender Sieg für Napoleon, der durch seine taktische Genialität gelang. Sie stärkte Frankreichs Position in Europa erheblich und führte zu einer geopolitischen Neuordnung, die die europäischen Mächte nachhaltig beeinflusste."}]'::jsonb, ''),
  ('befreiungskriag', 'Befreiungskriag', '', '', '', '', 'Befreiungskriege', '[{"kategorie": "hist.", "text": "\"Reihe von militärischen Konflikten, in denen sich europäische Staaten unter Führung von Preußen, Russland, Österreich und Großbritannien gegen die Vorherrschaft Napoleons und das Französische Kaiserreich auflehnten (1813–1815)\""}, {"kategorie": "", "text": "Diese Kriege führten schließlich zum Sturz Napoleons und zur Wiederherstellung der alten Machtverhältnisse in Europa"}, {"kategorie": "", "text": "Nach Napoleons gescheitertem Russlandfeldzug 1812 nutzten die europäischen Staaten die Schwäche Frankreichs, um die französische Besetzung und den Einfluss Napoleons in Europa zurückzudrängen. Die antinapoleonischen Koalitionen formierten sich neu und begannen eine Offensive gegen Frankreich und seine Verbündeten"}, {"kategorie": "", "text": "Die Befreiungskriege hatten das Ziel, die französische Besatzung zu beenden, nationale Unabhängigkeit wiederherzustellen und die Macht Napoleons zu brechen"}, {"kategorie": "", "text": "Wichtige Schlachten: (i) Schlacht bei Großgörschen (Mai 1813) und Schlacht bei Dresden (August 1813) waren anfängliche französische Siege.\nDie [[Schlacht]] bei Leipzig (Oktober 1813), auch [[Völkerschlacht]] genannt, war der Wendepunkt und endete mit einer Niederlage Napoleons"}, {"kategorie": "", "text": "Die Befreiungskriege endeten 1814 mit der Eroberung von Paris und der ersten Abdankung Napoleons, der ins Exil nach Elba geschickt wurde"}, {"kategorie": "", "text": "Nach seiner kurzen Rückkehr während der Herrschaft der Hundert Tage und der Niederlage bei Waterloo im Juni 1815 wurde Napoleon endgültig besiegt und ins Exil auf die Insel St. Helena verbannt"}, {"kategorie": "", "text": "Die Befreiungskriege führten zur Neuordnung Europas auf dem [[Wiener]] Kongress (1814/15), bei dem die monarchischen Mächte die alte politische Ordnung wiederherstellten. Sie gelten als Beginn eines nationalen Bewusstseins, insbesondere in Deutschland und Österreich, und als Meilenstein in der Entwicklung europäischer Nationalbewegungen."}]'::jsonb, ''),
  ('voelkaschlocht', 'Völkaschlocht', '', '', '', '', 'Völkerschlacht', '[{"kategorie": "hist.", "text": "\"Schlacht, welche vom 16. bis 19. Oktober 1813 stattfand und die größte Schlacht der [[Napoleonischen]] Kriege war (auch als \"Schlacht bei Leipzig\" bekannt)"}, {"kategorie": "", "text": "Die Schlacht endete mit einer Niederlage Napoleons und führte letztlich zum Ende seiner Vorherrschaft in Europa"}, {"kategorie": "", "text": "Die Schlacht bei Leipzig war Teil der [[Befreiungskriege]], bei denen sich Österreich, Preußen, Russland und Schweden gegen die französische Herrschaft stellten. Nach Napoleons gescheitertem Russlandfeldzug 1812 wollten die Koalitionsmächte Frankreich aus Deutschland vertreiben"}, {"kategorie": "", "text": "Auf der einen Seite stand Napoleons Armee mit etwa 185.000 Soldaten; auf der anderen die Koalition mit rund 320.000 Soldaten aus Österreich, Preußen, Russland und Schweden"}, {"kategorie": "", "text": "Die Kämpfe dauerten vier Tage und waren heftig. Die Koalitionsarmeen griffen Napoleons Truppen aus mehreren Richtungen an. Napoleon verteidigte sich zunächst erfolgreich, doch die zahlenmäßige Überlegenheit der Koalition zwang ihn letztlich zum Rückzug"}, {"kategorie": "", "text": "Die Schlacht war äußerst blutig, mit insgesamt rund 90.000 Toten und Verwundeten. Die Verluste führten zu einem erheblichen Schwächungseffekt für Napoleons Armee"}, {"kategorie": "", "text": "Die Niederlage zwang Napoleon zum Rückzug aus Deutschland und bereitete den Weg für den Einmarsch der Koalitionstruppen nach Frankreich. Die Schlacht bei Leipzig leitete das Ende von Napoleons Herrschaft ein und führte 1814 zu seiner Abdankung und Exilierung nach Elba."}]'::jsonb, ''),
  ('keenigtum', 'Keenigtum', '', '', '', '', 'Königtum', '[{"kategorie": "hist.", "text": "\"Herrschaftsform, die eng mit der Entwicklung des [[Habsburgerreiches]] und des [[Heiligen]] Römischen Reiches verbunden sind, aber nicht explizit die Herrschaftsform \"Königreich Österreich\" umfassen\""}, {"kategorie": "", "text": "Stattdessen prägte das [[Kaisertum]], insbesondere ab 1804 mit der Gründung des [[Kaisertums]] Österreich, die österreichische [[Monarchie]]"}, {"kategorie": "", "text": "Obwohl die [[Habsburger]] mehrere Königreiche regierten, wie Böhmen und Ungarn, und der Titel \"König\" zu ihrem Herrschaftsbereich gehörte, gab es keinen spezifischen \"König von Österreich\". Stattdessen beherrschten sie ein Vielvölkerreich, dessen Herzstück Österreich war"}, {"kategorie": "", "text": "Die Habsburger waren seit dem Mittelalter häufig römisch-deutsche Könige und [[Kaiser]] des Heiligen Römischen Reiches. Der Königstitel war oft mit dem Ziel verknüpft, den Kaisertitel zu erlangen. Der römisch-deutsche Königstitel war eine Vorstufe zur Kaiserwürde und galt als prestigeträchtige Position im Reich"}, {"kategorie": "", "text": "Nach der Auflösung des [[Heiligen]] Römischen Reiches 1806 und Napoleons wachsender Bedrohung erklärte Kaiser [[Franz]] II. das [[Kaisertum]] Österreich (1804) und wurde als [[Franz]] I. Kaiser von Österreich. Dies stellte sicher, dass die Habsburger weiterhin einen imperialen Titel führten, auch ohne das Heilige Römische Reich"}, {"kategorie": "", "text": "Die Habsburger behielten separate Königstitel für die Länder der böhmischen und ungarischen Krone, die offiziell bis zur Auflösung der Monarchie 1918 Bestand hatten. Die österreichischen Kaiser waren somit Könige von Ungarn und Böhmen, aber nicht „Könige von Österreich“"}, {"kategorie": "", "text": "Die habsburgische Dynastie vereinte viele Titel in einer Person und herrschte als Könige und Kaiser über eine Vielzahl an Königreichen und Fürstentümern, die ab 1867 zum österreichisch-ungarischen [[Doppelmonarchie]] wurden, was den Titel „König von Ungarn“ für die Habsburger wieder aufwertete."}]'::jsonb, ''),
  ('quadruplallianz', 'Quadruplallianz', '', '', '', '', 'Quadrupelallianz', '[{"kategorie": "hist.", "text": "\"Bündnis zwischen den vier Großmächten Großbritannien, Österreich, Preußen und Russland, das am 20. November 1815 geschlossen wurde, unmittelbar nach der endgültigen Niederlage [[Napoleons]] bei Waterloo und seinem Exil auf St. Helena\""}, {"kategorie": "", "text": "Ziel dieser Allianz war es, die Nachkriegsordnung in Europa, wie sie beim [[Wiener]] Kongress (1814–1815) festgelegt worden war, zu sichern und zukünftige revolutionäre oder imperialistische Bedrohungen zu verhindern"}, {"kategorie": "", "text": "Die Quadrupelallianz organisierte mehrere internationale Kongresse, darunter den Aachener Kongress (1818), den Troppauer Kongress (1820) und den Laibacher Kongress (1821), um politische Fragen und Konflikte in Europa zu besprechen.\nSie unterstützte konservative Regierungen, wie z. B. bei der Unterdrückung von Aufständen in Spanien und Italien, um revolutionäre und liberale Bestrebungen zu verhindern"}, {"kategorie": "", "text": "1818 wurde Frankreich nach einem erfolgreichen Integrationsprozess als fünftes Mitglied aufgenommen, wodurch die Allianz zur Pentarchie wurde, ein System, das die fünf großen Mächte (Großbritannien, Frankreich, Österreich, Preußen und Russland) zur Stabilisierung Europas vereinte"}, {"kategorie": "", "text": "Die Allianz verlor in den 1820er Jahren an Kohäsion, als Differenzen zwischen den Mächten auftraten, insbesondere aufgrund der unterschiedlichen Ansichten Großbritanniens und der Kontinentalmächte zu Interventionen in anderen Staaten"}, {"kategorie": "", "text": "Dennoch bildete die Quadrupelallianz eine Grundlage für die Friedenssicherung und das Gleichgewicht der Mächte in Europa und prägte die europäische Politik im frühen 19. Jahrhundert maßgeblich."}]'::jsonb, ''),
  ('heaschoftsinsigniin', 'Heaschoftsinsigniin', '', '', '', '', 'Herrschaftsinsignien', '[{"kategorie": "", "text": "Bestandteile der Habsburgischen Reichsinsignien: (i) die [[Kaiserkrone]] (die zentrale Krone der Insignien ist die [[Rudolfskrone]], die 1602 für Kaiser Rudolf II. angefertigt wurde. Sie war später, ab 1806, die Kaiserkrone des [[Kaisertums]] Österreich und symbolisierte die kaiserliche Würde und Macht der [[Habsburger]]),  (ii) Zepter und Reichsapfel (diese beiden Objekte sind weitere wesentliche Bestandteile der [[Insignien]]. Das [[Zepter]] steht für die weltliche Macht des [[Kaisers]], während der [[Reichsapfel]] - ein goldener, kugelförmiger Gegenstand - die Herrschaft über die Welt symbolisiert),  (iii) [[Reichsschwert]] (dieses Schwert wurde ebenfalls bei Krönungen und feierlichen Anlässen verwendet und diente als Symbol der Verteidigung des Reiches und der kaiserlichen Macht),  (iv) Krönungsmantel (der Krönungsmantel ist ein textiles Symbol für die königliche oder kaiserliche Würde),  (v) [[Heilige]] Lanze (ein weiteres Objekt, das oft zu den Reichsinsignien gezählt wird, ist die sogenannte Heilige Lanze, die als Symbol der kaiserlichen Macht und des Schutzes des Reiches diente)"}, {"kategorie": "", "text": "Die [[Habsburger]] behielten die Kontrolle über die [[Reichsinsignien]] während ihrer langen Herrschaft über das [[Heilige]] Römische Reich und später über das [[Kaisertum]] Österreich. Nach der Auflösung des Heiligen Römischen Reiches 1806 und der Gründung des Kaisertums Österreich blieben die Insignien ein wichtiges Symbol der habsburgischen Herrschaft"}, {"kategorie": "", "text": "Die Reichsinsignien symbolisierten die göttliche Berufung des Herrschers und seine Rolle als Beschützer des Reiches und des Christentums. wurden bei wichtigen Anlässen wie der Krönung des Kaisers verwendet, hatten eine starke symbolische Bedeutung und standen für die Vereinigung von geistlicher und weltlicher Macht"}, {"kategorie": "", "text": "Die Habsburgischen Herrschaftsinsignien sind eine bedeutende Sammlung zeremonieller Objekte, die die kaiserliche Macht der Habsburgerdynastie verkörpern und heute allesamt in der [[Wiener]] Schatzkammer der [[Hofburg]] besichtigt werden können."}]'::jsonb, ''),
  ('reichsinsigniin', 'Reichsinsigniin', '', '', '', '', 'Reichsinsignien', '[{"kategorie": "", "text": "Bestandteile der Habsburgischen Reichsinsignien: (i) die [[Kaiserkrone]] (die zentrale Krone der Insignien ist die [[Rudolfskrone]], die 1602 für Kaiser Rudolf II. angefertigt wurde. Sie war später, ab 1806, die Kaiserkrone des [[Kaisertums]] Österreich und symbolisierte die kaiserliche Würde und Macht der [[Habsburger]]),  (ii) Zepter und Reichsapfel (diese beiden Objekte sind weitere wesentliche Bestandteile der [[Insignien]]. Das [[Zepter]] steht für die weltliche Macht des [[Kaisers]], während der [[Reichsapfel]] - ein goldener, kugelförmiger Gegenstand - die Herrschaft über die Welt symbolisiert),  (iii) [[Reichsschwert]] (dieses Schwert wurde ebenfalls bei Krönungen und feierlichen Anlässen verwendet und diente als Symbol der Verteidigung des Reiches und der kaiserlichen Macht),  (iv) Krönungsmantel (der Krönungsmantel ist ein textiles Symbol für die königliche oder kaiserliche Würde),  (v) [[Heilige]] Lanze (ein weiteres Objekt, das oft zu den Reichsinsignien gezählt wird, ist die sogenannte Heilige Lanze, die als Symbol der kaiserlichen Macht und des Schutzes des Reiches diente)"}, {"kategorie": "", "text": "Die [[Habsburger]] behielten die Kontrolle über die [[Reichsinsignien]] während ihrer langen Herrschaft über das [[Heilige]] Römische Reich und später über das [[Kaisertum]] Österreich. Nach der Auflösung des Heiligen Römischen Reiches 1806 und der Gründung des Kaisertums Österreich blieben die Insignien ein wichtiges Symbol der habsburgischen Herrschaft"}, {"kategorie": "", "text": "Die Reichsinsignien symbolisierten die göttliche Berufung des Herrschers und seine Rolle als Beschützer des Reiches und des Christentums. wurden bei wichtigen Anlässen wie der Krönung des Kaisers verwendet, hatten eine starke symbolische Bedeutung und standen für die Vereinigung von geistlicher und weltlicher Macht"}, {"kategorie": "", "text": "Die Habsburgischen Reichsinsignien sind eine bedeutende Sammlung zeremonieller Objekte, die die kaiserliche Macht der Habsburgerdynastie verkörpern und heute allesamt in der [[Wiener]] Schatzkammer der [[Hofburg]] besichtigt werden können."}]'::jsonb, ''),
  ('insigniin', 'Insigniin', '', '', '', '', 'Insignien', '[{"kategorie": "allg.", "text": "\"symbolische Gegenstände, die die Macht, Würde und Autorität eines Amtes oder einer Herrschaftsposition repräsentieren\""}, {"kategorie": "", "text": "Insignien werden häufig bei zeremoniellen Anlässen verwendet, wie Krönungen oder Amtseinführungen, um den Status und die Legitimität des Amtsinhabers zu verdeutlichen. Sie können weltliche oder religiöse Bedeutung haben und sind oft aufwendig gestaltet, um die Bedeutung des Amtes zu unterstreichen"}, {"kategorie": "", "text": "Wichtige Insignien sind: (i) [[Krone]]: (symbolisiert die monarchische Herrschaft und wird traditionell von [[Königen]] und [[Kaisern]] getragen),  (ii) [[Zepter]] (ein Herrschaftsstab, der die Regierungsgewalt und Autorität des Trägers repräsentiert),  (iii) [[Reichsapfel]] (ein kugelförmiges Objekt, das die Weltmacht oder den universalen Herrschaftsanspruch symbolisiert),  (iv) [[Reichsschwert]] bzw. Schwert (steht oft für die militärische Macht und die Pflicht, das Reich zu verteidigen),  (v) Krönungsmantel (der Krönungsmantel ist ein textiles Symbol für die königliche oder kaiserliche Würde), sowie (vi) [[Heilige]] Lanze (dient als Symbol der kaiserlichen Macht und des Schutzes des Reiches)"}, {"kategorie": "", "text": "Insignien können sowohl politische ([[Krone]], [[Zepter]]) als auch religiöse Bedeutung haben (wie die [[Tiara]] oder das [[Pallium]] des Papstes)."}]'::jsonb, ''),
  ('reichszepta', 'Reichszepta', '', '', '', '', 'Reichszepter', '[{"kategorie": "hist.", "text": "\"zeremonieller Herrschaftsstab und ein Symbol der königlichen oder kaiserlichen Macht und Autorität\""}, {"kategorie": "", "text": "Das Zepter ist eines der bedeutenden Herrschaftsinsignien, die den [[Kaiser]] des Heiligen Römischen Reiches und später den [[Kaiser]] von Österreich repräsentierten"}, {"kategorie": "", "text": "Das Zepter symbolisiert die Souveränität, Macht und das Recht zu regieren und wird zusammen mit [[Krone]] und [[Reichsapfel]] traditionell bei der Krönung und anderen feierlichen Anlässen verwendet"}, {"kategorie": "", "text": "Für die Kaiser des Heiligen Römischen Reiches hatte das Zepter eine sakrale und politische Bedeutung, da es ihre Rolle als Beschützer des Reiches und der Kirche unterstrich"}, {"kategorie": "", "text": "Die [[Wiener]] Schatzkammer im [[Hofburg-Palast]] in Wien bewahrt das [[Reichszepter]] des Heiligen Römischen Reiches, das zusammen mit der [[Reichskrone]] und dem [[Reichsapfel]] zu den wichtigsten [[Reichsinsignien]] gehört"}, {"kategorie": "", "text": "Das Zepter stammt vermutlich aus dem 14. Jahrhundert und besteht aus Gold und Edelsteinen. Es ist kunstvoll gestaltet und zeigt meisterhafte Goldschmiedearbeit;  Nach der Auflösung des [[Heiligen]] Römischen Reiches im Jahr 1806 und der Gründung des [[Kaisertums]] Österreich (1804) führten die [[Habsburger]] weiterhin zeremonielle Insignien wie Zepter und Krone als Symbole der Herrschaft über ihr Kaiserreich. Das Zepter als Insignie des österreichischen Kaisers behielt seine repräsentative Funktion und wurde bei wichtigen Anlässen verwendet, obwohl keine formelle Krönung mehr stattfand"}, {"kategorie": "", "text": "Das Zepter und die anderen Herrschaftsinsignien, die heute in der [[Wiener]] Schatzkammer ausgestellt sind, sind wichtige Symbole der habsburgischen Dynastie und des ehemaligen Kaisertums Österreich. Sie erinnern an die Bedeutung und den Glanz der [[Habsburger]] Monarchie und ziehen zahlreiche Besucher an."}]'::jsonb, ''),
  ('zepta', 'Zepta', '', '', '', '', 'Zepter', '[{"kategorie": "hist.", "text": "\"zeremonieller Herrschaftsstab und ein Symbol der königlichen oder kaiserlichen Macht und Autorität\""}, {"kategorie": "", "text": "Das Zepter ist eines der bedeutenden Herrschaftsinsignien, die den [[Kaiser]] des Heiligen Römischen Reiches und später den [[Kaiser]] von Österreich repräsentierten"}, {"kategorie": "", "text": "Das Zepter symbolisiert die Souveränität, Macht und das Recht zu regieren und wird zusammen mit [[Krone]] und [[Reichsapfel]] traditionell bei der Krönung und anderen feierlichen Anlässen verwendet"}, {"kategorie": "", "text": "Für die Kaiser des Heiligen Römischen Reiches hatte das Zepter eine sakrale und politische Bedeutung, da es ihre Rolle als Beschützer des Reiches und der Kirche unterstrich"}, {"kategorie": "", "text": "Die [[Wiener]] Schatzkammer im [[Hofburg-Palast]] in Wien bewahrt das [[Reichszepter]] des Heiligen Römischen Reiches, das zusammen mit der [[Reichskrone]] und dem [[Reichsapfel]] zu den wichtigsten [[Reichsinsignien]] gehört"}, {"kategorie": "", "text": "Das Zepter stammt vermutlich aus dem 14. Jahrhundert und besteht aus Gold und Edelsteinen. Es ist kunstvoll gestaltet und zeigt meisterhafte Goldschmiedearbeit;  Nach der Auflösung des [[Heiligen]] Römischen Reiches im Jahr 1806 und der Gründung des [[Kaisertums]] Österreich (1804) führten die [[Habsburger]] weiterhin zeremonielle Insignien wie Zepter und Krone als Symbole der Herrschaft über ihr Kaiserreich. Das Zepter als Insignie des österreichischen Kaisers behielt seine repräsentative Funktion und wurde bei wichtigen Anlässen verwendet, obwohl keine formelle Krönung mehr stattfand"}, {"kategorie": "", "text": "Das Zepter und die anderen Herrschaftsinsignien, die heute in der [[Wiener]] Schatzkammer ausgestellt sind, sind wichtige Symbole der habsburgischen Dynastie und des ehemaligen Kaisertums Österreich. Sie erinnern an die Bedeutung und den Glanz der [[Habsburger]] Monarchie und ziehen zahlreiche Besucher an."}]'::jsonb, ''),
  ('reichsschweat', 'Reichsschweat', '', '', '', '', 'Reichsschwert', '[{"kategorie": "hist.", "text": "\"bedeutsames Herrschaftsinsigne und Bestandteil der Krönungsinsignien des [[Heiligen]] Römischen Reiches\""}, {"kategorie": "", "text": "Das Reichsschwert symbolisiert die richterliche und militärische Gewalt des [[Kaisers]] und verkörpert die Aufgabe, das Reich zu verteidigen und Recht und Ordnung zu bewahren"}, {"kategorie": "", "text": "Das Reichsschwert des Heiligen Römischen Reiches befindet sich heute in derà Wiener Schatzkammer und gilt als eine der wichtigsten Relikte des mittelalterlichen Kaisertums"}, {"kategorie": "", "text": "Das Reichsschwert steht für die Verteidigung des christlichen Glaubens und des Reiches, ebenso wie für die richterliche Gewalt des Kaisers. Es symbolisiert die Pflicht des Kaisers, Gerechtigkeit zu üben und das Reich vor äußeren Feinden zu schützen. Zusammen mit der [[Reichskrone]], dem [[Reichsapfel]] und dem [[Zepter]] bildet das Reichsschwert die Hauptinsignien des Heiligen Römischen Reiches und ist Ausdruck der kaiserlichen Autorität und Ehre"}, {"kategorie": "", "text": "Das Reichsschwert wird seit Jahrhunderten in der [[Wiener]] Schatzkammer in der [[Hofburg]] in Wien aufbewahrt, zusammen mit weiteren Reichsinsignien wie der [[Reichskrone]] und dem [[Reichsapfel]]. Das Schwert selbst stammt vermutlich aus dem 11. Jahrhundert und hat eine Länge von etwa 110 cm. Der Knauf und das Kreuz sind aus vergoldetem Silber gefertigt, und die Klinge ist aufwendig gearbeitet"}, {"kategorie": "", "text": "Das Reichsschwert spielte eine zentrale Rolle bei den Krönungszeremonien des römisch-deutschen Kaisers, wo es als Symbol der kaiserlichen Macht und Verantwortung überreicht wurde. Es wurde oft von einem hohen Würdenträger vor dem Kaiser getragen und in feierlichen Prozessionen gezeigt. Es diente auch bei anderen wichtigen Zeremonien und kaiserlichen Anlässen als Zeichen der kaiserlichen Macht und Schutzfunktion"}, {"kategorie": "", "text": "Nach dem Ende des Heiligen Römischen Reiches blieb das Reichsschwert als Teil der habsburgischen Herrschaftsinsignien in Österreich und ist heute ein bedeutendes Ausstellungsstück der Wiener Schatzkammer. Es repräsentiert die habsburgische Verbindung zur Geschichte des Heiligen Römischen Reiches und die Rolle der [[Habsburger]] als letzte Herrscher des Reiches."}]'::jsonb, '')
